window.TELC_SPRECHEN = [{"no":1,"title":"Arbeitszeiten in der Gastronomie","A":{"who":"Herr Klausen, 55 Jahre alt, Soldat","text":"Ich bin mein eigener Chef, deshalb habe ich nicht geregelte Arbeitszeiten. Zum Glück läuft mein Bekleidungsgeschäft gut. Obwohl ich sehr wenig Urlaub machen kann und immer abends und am Wochenende arbeiten muss, will ich nicht klagen."},"B":{"who":"Frau Haffner, 43 Jahre alt, Tierärztin","text":"Zurzeit arbeite ich Teilzeit, d.h. nur vormittags. Neben der Hausarbeit muss ich mich um unsere kleinen Kinder kümmern. In ein paar Jahren, wenn sie erwachsen sind, möchte ich wieder ganztags arbeiten. Darüber habe ich auch schon mit meinem Mann gesprochen. Er wird mich immer unterstützen."},"en":"Working hours in the catering trade","sol":{"A":[{"de":"<strong>Es geht um das Thema</strong> „Arbeitszeiten in der Gastronomie“.","tag":"Opener 1","en":"The topic is \"working hours in restaurants\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> ein Mann, <strong>dass</strong> er sein eigener Chef ist und deshalb abends und am Wochenende arbeiten muss.","tag":"Opener 2","en":"On my task sheet a man says that he is his own boss and therefore has to work in the evenings and at weekends."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> viele Selbstständige keine festen Arbeitszeiten haben.","tag":"Opener 3","en":"I find this opinion interesting, because many self-employed people have no fixed working hours."},{"de":"<strong>Meiner Meinung nach ist Qualität wichtiger als der Preis.</strong>","tag":"Family 5, opinion","en":"In my opinion quality is more important than the price."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass Bus und Bahn in der Stadt oft schneller sind als das Auto.</strong>","tag":"Family 5, experience","en":"I have found that buses and trains in the city are often faster than the car."},{"de":"<strong>In meinem Heimatland fahren die meisten Leute mit dem Auto oder mit dem Motorrad.</strong>","tag":"Family 5, home country","en":"In my home country most people travel by car or by motorbike."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}],"B":[{"de":"<strong>Es geht um das Thema</strong> „Arbeitszeiten in der Gastronomie“.","tag":"Opener 1","en":"The topic is \"working hours in restaurants\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> eine Frau, <strong>dass</strong> sie zurzeit nur vormittags arbeitet und sich um ihre kleinen Kinder kümmert.","tag":"Opener 2","en":"On my task sheet a woman says that she currently works only in the mornings and looks after her small children."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> viele Mütter erst wieder ganztags arbeiten, wenn die Kinder älter sind.","tag":"Opener 3","en":"I find this opinion interesting, because many mothers only work full time again when the children are older."},{"de":"<strong>Meiner Meinung nach ist Qualität wichtiger als der Preis.</strong>","tag":"Family 5, opinion","en":"In my opinion quality is more important than the price."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass Bus und Bahn in der Stadt oft schneller sind als das Auto.</strong>","tag":"Family 5, experience","en":"I have found that buses and trains in the city are often faster than the car."},{"de":"<strong>In meinem Heimatland fahren die meisten Leute mit dem Auto oder mit dem Motorrad.</strong>","tag":"Family 5, home country","en":"In my home country most people travel by car or by motorbike."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}]}},{"no":2,"title":"Geld","A":{"who":"Enrico Sammer, 34 Jahre, Optiker","text":"Ich bin eine sparsame Person und muss nachdenken, was ich kaufen soll. Überflüssige und teure Dinge kaufe ich auf keinen Fall. Mir ist es wichtig, Geld zu sparen."},"B":{"who":"Nicole Streidel, 25 Jahre, Floristin","text":"Ich erhalte meinen Lohn, um shoppen zu gehen. Ich kaufe alles, was mir gefällt. Mir ist egal, ob ich diese Dinge wirklich brauche oder nicht. Man lebt ja nur einmal."},"en":"Money","sol":{"A":[{"de":"<strong>Es geht um das Thema</strong> „Geld“.","tag":"Opener 1","en":"The topic is \"money\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> ein Mann, <strong>dass</strong> er sparsam ist und keine überflüssigen, teuren Dinge kauft.","tag":"Opener 2","en":"On my task sheet a man says that he is thrifty and does not buy unnecessary, expensive things."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> Sparen für die Zukunft wichtig ist.","tag":"Opener 3","en":"I find this opinion interesting, because saving is important for the future."},{"de":"<strong>Meiner Meinung nach ist Qualität wichtiger als der Preis.</strong>","tag":"Family 5, opinion","en":"In my opinion quality is more important than the price."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass Bus und Bahn in der Stadt oft schneller sind als das Auto.</strong>","tag":"Family 5, experience","en":"I have found that buses and trains in the city are often faster than the car."},{"de":"<strong>In meinem Heimatland fahren die meisten Leute mit dem Auto oder mit dem Motorrad.</strong>","tag":"Family 5, home country","en":"In my home country most people travel by car or by motorbike."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}],"B":[{"de":"<strong>Es geht um das Thema</strong> „Geld“.","tag":"Opener 1","en":"The topic is \"money\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> eine junge Frau, <strong>dass</strong> sie ihren Lohn gern fürs Shoppen ausgibt.","tag":"Opener 2","en":"On my task sheet a young woman says that she likes to spend her wages on shopping."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> man ja nur einmal lebt.","tag":"Opener 3","en":"I find this opinion interesting, because you only live once."},{"de":"<strong>Meiner Meinung nach ist Qualität wichtiger als der Preis.</strong>","tag":"Family 5, opinion","en":"In my opinion quality is more important than the price."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass Bus und Bahn in der Stadt oft schneller sind als das Auto.</strong>","tag":"Family 5, experience","en":"I have found that buses and trains in the city are often faster than the car."},{"de":"<strong>In meinem Heimatland fahren die meisten Leute mit dem Auto oder mit dem Motorrad.</strong>","tag":"Family 5, home country","en":"In my home country most people travel by car or by motorbike."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}]}},{"no":3,"title":"Stress","A":{"who":"Susi, 27 Jahre alt, Krankenpflegerin","text":"Ich bin sehr beschäftigt. Die Arbeit wächst mir langsam über den Kopf. Aus diesem Grund bin ich immer sehr erschöpft. Für meine eigenen Interessen und zum Entspannen will ich mehr Zeit verbringen. Auch mit meinem Mann und den Kindern möchte ich mehr unternehmen."},"B":{"who":"Dieter, 49 Jahre alt, Journalist","text":"Eine sehr lebhafte und neugierige Person . Für mich ist die Abwechslung im Leben wichtig. Ich habe keine Ahnung, was Stress bedeutet. Ich bin immer unterwegs und das macht mir Spaß. Ich fühle mich wohl, wenn ich viel zu tun habe."},"en":"Stress","tr":{"A":"Susi, 27, nurse: \"I am very busy. The work is slowly getting too much for me. For this reason I am always very exhausted. I want to spend more time on my own interests and on relaxing. I also want to do more with my husband and the children.\"","B":"Dieter, 49, journalist: \"A very lively and curious person. For me, variety in life is important. I have no idea what stress means. I am always on the go and I enjoy that. I feel good when I have a lot to do.\""},"sol":{"A":[{"de":"<strong>Es geht um das Thema</strong> „Stress“.","tag":"Opener 1","en":"The topic is \"stress\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt eine junge Frau, dass</strong> ihr die Arbeit über den Kopf wächst. Sie ist immer sehr müde.","tag":"Opener 2","en":"On my task sheet a young woman says that her work is getting too much for her. She is always very tired."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> viele Menschen zu viel arbeiten.","tag":"Opener 3","en":"I find this opinion interesting, because many people work too much."},{"de":"<strong>Meiner Meinung nach ist Gesundheit wichtiger als alles andere.</strong>","tag":"Family 6, opinion (exact)","en":"In my opinion health is more important than anything else."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass ich mit Sport weniger Stress habe.</strong>","tag":"Family 6, experience (exact)","en":"I have found that I have less stress when I do sport."},{"de":"<strong>In meinem Heimatland</strong> spricht man wenig über Stress, aber viele Leute arbeiten sehr lange.","tag":"Family 6, home country (start only)","en":"In my home country people talk little about stress, but many people work very long hours."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}],"B":[{"de":"<strong>Es geht um das Thema</strong> „Stress“.","tag":"Opener 1","en":"The topic is \"stress\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> ein Mann, <strong>dass</strong> er keinen Stress kennt. Er hat gern viel zu tun.","tag":"Opener 2","en":"On my task sheet a man says that he does not know stress. He likes having a lot to do."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> viel Arbeit auch Spaß machen kann.","tag":"Opener 3","en":"I find this opinion interesting, because a lot of work can also be fun."},{"de":"<strong>Meiner Meinung nach ist Gesundheit wichtiger als alles andere.</strong>","tag":"Family 6, opinion (exact)","en":"In my opinion health is more important than anything else."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass ich mit Sport weniger Stress habe.</strong>","tag":"Family 6, experience (exact)","en":"I have found that I have less stress when I do sport."},{"de":"<strong>In meinem Heimatland</strong> spricht man wenig über Stress, aber viele Leute arbeiten sehr lange.","tag":"Family 6, home country (start only)","en":"In my home country people talk little about stress, but many people work very long hours."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}]}},{"no":4,"title":"Schöner Wohnen","A":{"who":"Bernd Rischer,m 46 Jahre, Architekt","text":"Ich liebe schöne Möbel und Bilder! In meiner Wohnung habe ich sogar ein paar Antiquitäten und moderne Designermöbel. Außerdem ist meine Wohnung immer aufgeräumt und alles hat seinen festen Platz. So fühle ich mich einfach wohl!"},"B":{"who":"Julia Lochner, 23 Jahre, Friseurin","text":"Für mich hat es keine Bedeutung, wie meine Einrichtung aussieht. Wichtig für mich ist. ob die Möbel bequem und praktisch sind. Die Qualität spielt auch eine wichtige Rolle. Denn wenn man Geld ausgibt, will man ja auch etwas davon haben."},"en":"Beautiful homes","sol":{"A":[{"de":"<strong>Es geht um das Thema</strong> „Schöner Wohnen“.","tag":"Opener 1","en":"The topic is \"making your home nice\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> ein Mann, <strong>dass</strong> er schöne Möbel und Bilder liebt und seine Wohnung immer aufgeräumt ist.","tag":"Opener 2","en":"On my task sheet a man says that he loves beautiful furniture and pictures and his flat is always tidy."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> man sich in einer schönen Wohnung wohlfühlt.","tag":"Opener 3","en":"I find this opinion interesting, because you feel at home in a beautiful flat."},{"de":"<strong>Meiner Meinung nach ist eine ruhige Lage wichtiger als eine große Wohnung.</strong>","tag":"Family 3, opinion","en":"In my opinion a quiet location is more important than a big flat."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass Wohnungen in München sehr teuer sind.</strong>","tag":"Family 3, experience","en":"I have found that flats in Munich are very expensive. (Use your own city.)"},{"de":"<strong>In meinem Heimatland wohnen die Kinder meistens bei den Eltern, bis sie heiraten.</strong>","tag":"Family 3, home country","en":"In my home country children mostly live with their parents until they marry."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}],"B":[{"de":"<strong>Es geht um das Thema</strong> „Schöner Wohnen“.","tag":"Opener 1","en":"The topic is \"making your home nice\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> eine junge Frau, <strong>dass</strong> ihr das Aussehen der Einrichtung nicht wichtig ist, sondern dass die Möbel bequem und praktisch sind.","tag":"Opener 2","en":"On my task sheet a young woman says that the look of the furnishings is not important to her, but that the furniture is comfortable and practical."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> Möbel vor allem nützlich sein sollen.","tag":"Opener 3","en":"I find this opinion interesting, because furniture should above all be useful."},{"de":"<strong>Meiner Meinung nach ist eine ruhige Lage wichtiger als eine große Wohnung.</strong>","tag":"Family 3, opinion","en":"In my opinion a quiet location is more important than a big flat."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass Wohnungen in München sehr teuer sind.</strong>","tag":"Family 3, experience","en":"I have found that flats in Munich are very expensive. (Use your own city.)"},{"de":"<strong>In meinem Heimatland wohnen die Kinder meistens bei den Eltern, bis sie heiraten.</strong>","tag":"Family 3, home country","en":"In my home country children mostly live with their parents until they marry."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}]}},{"no":5,"title":"Lebenslanges Lernen","A":{"who":"Karsten Dressel, 26 Jahre alt, Student","text":"Nach meinem Abitur habe ich mit dem Studium angefangen. Auf keinen Fall möchte ich nicht weiter lernen. Irgendwann reicht es. Nun möchte ich Zeit verbringen, Geld zu verdienen und die Freizeit zu genießen. Ich hätte gern auch Zeit für mich und meine Familie."},"B":{"who":"Lena Weise, 32 Jahre alt, Finanzbeamtin","text":"Aus meiner Sicht sollte man stets versuchen, etwas Neues zu erlernen. Je mehr die Welt sich ändert und entwickelt, desto mehr sollten wir lernen. Man kann es sich einfach nicht leisten, „stehen zu bleiben“. Deshalb nehme ich oft an Kursen teil, um mein Wissen aufzufrischen."},"en":"Lifelong learning","sol":{"A":[{"de":"<strong>Es geht um das Thema</strong> „Lebenslanges Lernen“.","tag":"Opener 1","en":"The topic is \"lifelong learning\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> ein junger Mann, <strong>dass</strong> er nach dem Studium nicht mehr weiterlernen, sondern Geld verdienen und mehr Zeit für seine Familie haben möchte.","tag":"Opener 2","en":"On my task sheet a young man says that after his studies he does not want to keep learning but wants to earn money and have more time for his family."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> man nach vielen Jahren Lernen auch einmal eine Pause braucht.","tag":"Opener 3","en":"I find this opinion interesting, because after many years of learning you also need a break."},{"de":"<strong>Meiner Meinung nach ist Qualität wichtiger als der Preis.</strong>","tag":"Family 5, opinion","en":"In my opinion quality is more important than the price."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass Bus und Bahn in der Stadt oft schneller sind als das Auto.</strong>","tag":"Family 5, experience","en":"I have found that buses and trains in the city are often faster than the car."},{"de":"<strong>In meinem Heimatland fahren die meisten Leute mit dem Auto oder mit dem Motorrad.</strong>","tag":"Family 5, home country","en":"In my home country most people travel by car or by motorbike."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}],"B":[{"de":"<strong>Es geht um das Thema</strong> „Lebenslanges Lernen“.","tag":"Opener 1","en":"The topic is \"lifelong learning\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> eine Frau, <strong>dass</strong> man immer etwas Neues lernen sollte und sie deshalb oft Kurse besucht.","tag":"Opener 2","en":"On my task sheet a woman says that you should always learn something new and that is why she often attends courses."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> sich die Welt schnell verändert.","tag":"Opener 3","en":"I find this opinion interesting, because the world changes quickly."},{"de":"<strong>Meiner Meinung nach ist Qualität wichtiger als der Preis.</strong>","tag":"Family 5, opinion","en":"In my opinion quality is more important than the price."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass Bus und Bahn in der Stadt oft schneller sind als das Auto.</strong>","tag":"Family 5, experience","en":"I have found that buses and trains in the city are often faster than the car."},{"de":"<strong>In meinem Heimatland fahren die meisten Leute mit dem Auto oder mit dem Motorrad.</strong>","tag":"Family 5, home country","en":"In my home country most people travel by car or by motorbike."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}]}},{"no":6,"title":"Sport treiben","A":{"who":"Manuel Gertz, 41 Jahre, Förster","text":"Ich treibe täglich Sport. Mir ist egal, ob das Wetter schön oder schlecht ist. Ich jogge eine Stunde um den See herum. Am liebsten, wenn die Sonne untergeht. Dann fühle ich mich wohl."},"B":{"who":"Patrizia Schröder, 28 Jahre, Metzgerin","text":"Sport ist stressig. Wenn meine Beschäftigung beendet ist, kleide ich mich bequem an und entspanne mich im Sessel. Dazu höre ich Jazz und lese Comics."},"en":"Doing sport","sol":{"A":[{"de":"<strong>Es geht um das Thema</strong> „Sport treiben“.","tag":"Opener 1","en":"The topic is \"doing sport\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> ein Mann, <strong>dass</strong> er jeden Tag Sport treibt und eine Stunde um den See joggt.","tag":"Opener 2","en":"On my task sheet a man says that he does sport every day and jogs around the lake for an hour."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> Bewegung gut für die Gesundheit ist.","tag":"Opener 3","en":"I find this opinion interesting, because exercise is good for your health."},{"de":"<strong>Meiner Meinung nach ist Gesundheit wichtiger als alles andere.</strong>","tag":"Family 6, opinion","en":"In my opinion health is more important than anything else."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass ich mit dem täglichen Spaziergang weniger Stress habe.</strong>","tag":"Family 6, experience","en":"I have found that I have less stress with my daily walk."},{"de":"<strong>In meinem Heimatland ist das Essen sehr scharf, und wir kochen fast jeden Tag frisch.</strong>","tag":"Family 6, home country","en":"In my home country the food is very spicy, and we cook fresh almost every day."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}],"B":[{"de":"<strong>Es geht um das Thema</strong> „Sport treiben“.","tag":"Opener 1","en":"The topic is \"doing sport\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> eine junge Frau, <strong>dass</strong> Sport für sie stressig ist und sie sich nach der Arbeit lieber entspannt.","tag":"Opener 2","en":"On my task sheet a young woman says that sport is stressful for her and she prefers to relax after work."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> man nach einem langen Arbeitstag auch Ruhe braucht.","tag":"Opener 3","en":"I find this opinion interesting, because you also need rest after a long working day."},{"de":"<strong>Meiner Meinung nach ist Gesundheit wichtiger als alles andere.</strong>","tag":"Family 6, opinion","en":"In my opinion health is more important than anything else."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass ich mit dem täglichen Spaziergang weniger Stress habe.</strong>","tag":"Family 6, experience","en":"I have found that I have less stress with my daily walk."},{"de":"<strong>In meinem Heimatland ist das Essen sehr scharf, und wir kochen fast jeden Tag frisch.</strong>","tag":"Family 6, home country","en":"In my home country the food is very spicy, and we cook fresh almost every day."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}]}},{"no":7,"title":"Beste Freunde","A":{"who":"Ella Wegmann, 23 Jahre, Studentin","text":"Schon seit meiner Kindheit lerne ich meine beste Freundin kennen. Sie wohnt zwar weit weg von mir, aber wir unterhalten uns ganz oft. Wir kennen uns sehr gut und erzählen uns alles. Konflikte gibt es zwischen uns überhaupt nicht."},"B":{"who":"Max Berger, 25 Jahre, Koch","text":"Ich habe keinen besten Freund. Aber durch meinen Sportverein kenne ich viele Bekannte. Wir haben das gemeinsame Hobby, Sport zu machen. Deshalb treffen wir uns am Wochenende und gehen zusammen zum Sport. Danach gehen wir ab und zu in die Kneipe."},"en":"Best friends","tr":{"A":"Ella Wegmann, 23, student: \"I have known my best friend since my childhood. She lives far away from me, but we talk very often. We know each other very well and tell each other everything. There are no conflicts between us at all.\"","B":"Max Berger, 25, cook: \"I do not have a best friend. But through my sports club I know many people. We share the hobby of doing sport. So we meet at the weekend and do sport together. Afterwards we sometimes go to the pub.\""},"sol":{"A":[{"de":"<strong>Es geht um das Thema</strong> „Beste Freunde“.","tag":"Opener 1","en":"The topic is \"best friends\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt eine junge Frau, dass</strong> sie ihre beste Freundin schon seit ihrer Kindheit kennt.","tag":"Opener 2","en":"On my task sheet a young woman says that she has known her best friend since her childhood."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> alte Freunde einen sehr gut kennen.","tag":"Opener 3","en":"I find this opinion interesting, because old friends know you very well."},{"de":"<strong>Meiner Meinung nach ist die Familie wichtiger als Geld oder Karriere.</strong>","tag":"Family 2, opinion","en":"In my opinion family is more important than money or career."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass gute Freunde in schweren Zeiten sehr wichtig sind.</strong>","tag":"Family 2, experience","en":"I have found that good friends are very important in hard times."},{"de":"<strong>In meinem Heimatland feiern wir oft mit der ganzen Familie, manchmal mit über hundert Gästen.</strong>","tag":"Family 2, home country","en":"In my home country we often celebrate with the whole family, sometimes with over a hundred guests."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}],"B":[{"de":"<strong>Es geht um das Thema</strong> „Beste Freunde“.","tag":"Opener 1","en":"The topic is \"best friends\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> ein junger Mann, <strong>dass</strong> er keinen besten Freund hat. Aber er kennt viele Leute aus seinem Sportverein.","tag":"Opener 2","en":"On my task sheet a young man says that he has no best friend. But he knows many people from his sports club."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> man auch durch ein Hobby neue Leute kennenlernt.","tag":"Opener 3","en":"I find this opinion interesting, because you also meet new people through a hobby."},{"de":"<strong>Meiner Meinung nach ist die Familie wichtiger als Geld oder Karriere.</strong>","tag":"Family 2, opinion","en":"In my opinion family is more important than money or career."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass gute Freunde in schweren Zeiten sehr wichtig sind.</strong>","tag":"Family 2, experience","en":"I have found that good friends are very important in hard times."},{"de":"<strong>In meinem Heimatland feiern wir oft mit der ganzen Familie, manchmal mit über hundert Gästen.</strong>","tag":"Family 2, home country","en":"In my home country we often celebrate with the whole family, sometimes with over a hundred guests."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}]}},{"no":8,"title":"Tanzen","A":{"who":"Marie Müller, 20 Jahre alt, Studentin","text":"Ich bin ein musikalischer Mensch und habe ein großes Interesse an Tanzen. Ich fühle mich sehr entspannend beim Tanzen. Ich habe auch schon an einigen Tanzkursen teilgenommen. An Wochenenden gehe ich regelmäßig mit Freundinnen in die Disko und genieße diese Zeit bis zur Erschöpfung. Ich habe viel Spaß dabei."},"B":{"who":"Martin Berger. 40 Jahre alt, Verkäufer","text":"Ich interessiere mich für Musikhören, aber Tanzen liegt mir nicht. Meine Frau wollte mich oft überreden, an einem Tanzkurs teilzunehmen. Aber das hat sie bis jetzt noch nicht geschafft. Ich will kein großer Tänzer werden."},"en":"Dancing","sol":{"A":[{"de":"<strong>Es geht um das Thema</strong> „Tanzen“.","tag":"Opener 1","en":"The topic is \"dancing\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> eine junge Frau, <strong>dass</strong> sie sehr gern tanzt und am Wochenende mit Freundinnen in die Disko geht.","tag":"Opener 2","en":"On my task sheet a young woman says that she loves dancing and goes to the disco with friends at the weekend."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> Tanzen Spaß macht und entspannt.","tag":"Opener 3","en":"I find this opinion interesting, because dancing is fun and relaxing."},{"de":"<strong>Meiner Meinung nach braucht jeder Mensch Zeit für seine Hobbys.</strong>","tag":"Family 4, opinion","en":"In my opinion every person needs time for their hobbies."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass ich nach einem langen Spaziergang viel entspannter bin.</strong>","tag":"Family 4, experience","en":"I have found that I am much more relaxed after a long walk."},{"de":"<strong>In meinem Heimatland verbringen viele Leute ihre Freizeit mit der Familie.</strong>","tag":"Family 4, home country","en":"In my home country many people spend their free time with their family."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}],"B":[{"de":"<strong>Es geht um das Thema</strong> „Tanzen“.","tag":"Opener 1","en":"The topic is \"dancing\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> ein Mann, <strong>dass</strong> er gern Musik hört, aber nicht tanzen möchte.","tag":"Opener 2","en":"On my task sheet a man says that he likes listening to music but does not want to dance."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> nicht jeder Mensch gern tanzt.","tag":"Opener 3","en":"I find this opinion interesting, because not everybody likes dancing."},{"de":"<strong>Meiner Meinung nach braucht jeder Mensch Zeit für seine Hobbys.</strong>","tag":"Family 4, opinion","en":"In my opinion every person needs time for their hobbies."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass ich nach einem langen Spaziergang viel entspannter bin.</strong>","tag":"Family 4, experience","en":"I have found that I am much more relaxed after a long walk."},{"de":"<strong>In meinem Heimatland verbringen viele Leute ihre Freizeit mit der Familie.</strong>","tag":"Family 4, home country","en":"In my home country many people spend their free time with their family."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}]}},{"no":9,"title":"Gefahren im Internet","A":{"who":"Matthias Schweiger, 31 Jahre, Bauingenieur","text":"Ich kaufe regelmäßig im Internet ein und erledige auch meine ganzen Bankgeschäfte online. Ich habe dabei keine Sorge, dass etwas passiert. Falschgeld, Betrug und Diebstahl gab es früher auch schon."},"B":{"who":"Janina Groß, 21 Jahre, Verkäuferin","text":"Ich kaufe ganz selten im Internet. Ich gehe lieber in richtige Geschäfte und lasse mich dort auch beraten. Außerdem gehe ich immer persönlich zu meiner Bank. So ist es fast unmöglich, dass andere Personen an meine Daten gelangen."},"en":"Dangers on the internet","sol":{"A":[{"de":"<strong>Es geht um das Thema</strong> „Gefahren im Internet“.","tag":"Opener 1","en":"The topic is \"dangers on the internet\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> ein Mann, <strong>dass</strong> er regelmäßig im Internet einkauft und keine Angst vor Betrug hat.","tag":"Opener 2","en":"On my task sheet a man says that he regularly shops online and is not afraid of fraud."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> das Internet für viele Menschen zum Alltag gehört.","tag":"Opener 3","en":"I find this opinion interesting, because the internet is part of everyday life for many people."},{"de":"<strong>Meiner Meinung nach ist das Handy praktisch, aber man sollte es nicht zu oft benutzen.</strong>","tag":"Family 1, opinion","en":"In my opinion the phone is practical, but you should not use it too often."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass ich ohne Handy besser schlafe und mehr Zeit für meine Familie habe.</strong>","tag":"Family 1, experience","en":"I have found that I sleep better without my phone and have more time for my family."},{"de":"<strong>In meinem Heimatland benutzen fast alle jungen Leute den ganzen Tag ihr Handy.</strong>","tag":"Family 1, home country","en":"In my home country almost all young people use their phones all day."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}],"B":[{"de":"<strong>Es geht um das Thema</strong> „Gefahren im Internet“.","tag":"Opener 1","en":"The topic is \"dangers on the internet\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> eine junge Frau, <strong>dass</strong> sie lieber im Geschäft einkauft und persönlich zur Bank geht.","tag":"Opener 2","en":"On my task sheet a young woman says that she prefers to shop in a shop and goes to the bank in person."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> man seine Daten so besser schützen kann.","tag":"Opener 3","en":"I find this opinion interesting, because you can protect your data better that way."},{"de":"<strong>Meiner Meinung nach ist das Handy praktisch, aber man sollte es nicht zu oft benutzen.</strong>","tag":"Family 1, opinion","en":"In my opinion the phone is practical, but you should not use it too often."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass ich ohne Handy besser schlafe und mehr Zeit für meine Familie habe.</strong>","tag":"Family 1, experience","en":"I have found that I sleep better without my phone and have more time for my family."},{"de":"<strong>In meinem Heimatland benutzen fast alle jungen Leute den ganzen Tag ihr Handy.</strong>","tag":"Family 1, home country","en":"In my home country almost all young people use their phones all day."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}]}},{"no":10,"title":"Hauskauf oder Mieten","A":{"who":"Andrea Wegmann. 35 Jahre, Taxifahrerin","text":"Vor 6 Jahren hatten mein Mann und ich unser eigenes Haus. Natürlich mussten wir sehr viel Geld dafür ausgeben. Aber die monatliche Miete ist auch zu hoch. Darüber hinaus sind ein Garten und viel Platz zum Spielen für unsere Kinder sehr wichtig."},"B":{"who":"Lina Müller, 23 Jahre, Reiseführerin","text":"Ein Haus besitzen? – Nein, das ist mir unwichtig. Denn ich lebe nur allein und brauche ein kleines Zimmer. Ich bin mir auch nicht sicher, ob ich in den nächsten Jahren aus beruflichen Gründen ins Ausland ziehen muss."},"en":"Buying a house or renting","sol":{"A":[{"de":"<strong>Es geht um das Thema</strong> „Hauskauf oder Mieten“.","tag":"Opener 1","en":"The topic is \"buying a house or renting\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> eine Frau, <strong>dass</strong> ein eigenes Haus mit Garten für ihre Familie besser ist als eine teure Mietwohnung.","tag":"Opener 2","en":"On my task sheet a woman says that a house of their own with a garden is better for her family than an expensive rented flat."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> Kinder Platz zum Spielen brauchen.","tag":"Opener 3","en":"I find this opinion interesting, because children need space to play."},{"de":"<strong>Meiner Meinung nach ist eine ruhige Lage wichtiger als eine große Wohnung.</strong>","tag":"Family 3, opinion","en":"In my opinion a quiet location is more important than a big flat."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass Wohnungen in München sehr teuer sind.</strong>","tag":"Family 3, experience","en":"I have found that flats in Munich are very expensive. (Use your own city.)"},{"de":"<strong>In meinem Heimatland wohnen die Kinder meistens bei den Eltern, bis sie heiraten.</strong>","tag":"Family 3, home country","en":"In my home country children mostly live with their parents until they marry."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}],"B":[{"de":"<strong>Es geht um das Thema</strong> „Hauskauf oder Mieten“.","tag":"Opener 1","en":"The topic is \"buying a house or renting\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> eine junge Frau, <strong>dass</strong> sie allein lebt, nur ein kleines Zimmer braucht und vielleicht ins Ausland zieht.","tag":"Opener 2","en":"On my task sheet a young woman says that she lives alone, only needs a small room and may move abroad."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> man als junger Mensch flexibel bleiben möchte.","tag":"Opener 3","en":"I find this opinion interesting, because as a young person you want to stay flexible."},{"de":"<strong>Meiner Meinung nach ist eine ruhige Lage wichtiger als eine große Wohnung.</strong>","tag":"Family 3, opinion","en":"In my opinion a quiet location is more important than a big flat."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass Wohnungen in München sehr teuer sind.</strong>","tag":"Family 3, experience","en":"I have found that flats in Munich are very expensive. (Use your own city.)"},{"de":"<strong>In meinem Heimatland wohnen die Kinder meistens bei den Eltern, bis sie heiraten.</strong>","tag":"Family 3, home country","en":"In my home country children mostly live with their parents until they marry."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}]}},{"no":11,"title":"Essen","A":{"who":"Sabine Helbig, 26 Jahre, Rezeptionistin","text":"Wegen der beschäftigen Arbeit kann ich nicht lange Mittagspause machen. Deshalb entscheide ich mich immer für einen schnellen Imbiss, der nebenan in einem kleinen Laden ist. Je nach Jahreszeit gibt es entweder einen frischen Salat oder nur Obst. Am Abend koche ich ein warmes Essen für meine Familie oder manchmal meinen Mann."},"B":{"who":"Jens Schneider, 24 Jahre, Praktikant","text":"Wir sind Auszubildende und mittags beschließen wir immer das Mittagessen in der Kantine. Es gibt dort eine große Auswahl an leckeren Gerichten. Ich interessiere mich dafür, dass ich mit freundlichen Kollegen essen kann. Nach einem anstrengenden Arbeitstag muss ich auch nicht selbst kochen, weil ich nur allein wohne."},"en":"Eating","sol":{"A":[{"de":"<strong>Es geht um das Thema</strong> „Essen“.","tag":"Opener 1","en":"The topic is \"food\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> eine junge Frau, <strong>dass</strong> sie mittags nur einen schnellen Imbiss isst und abends warm für ihre Familie kocht.","tag":"Opener 2","en":"On my task sheet a young woman says that she only has a quick snack at lunchtime and cooks a hot meal for her family in the evening."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> viele Menschen mittags wenig Zeit haben.","tag":"Opener 3","en":"I find this opinion interesting, because many people have little time at lunchtime."},{"de":"<strong>Meiner Meinung nach ist Gesundheit wichtiger als alles andere.</strong>","tag":"Family 6, opinion","en":"In my opinion health is more important than anything else."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass ich mit dem täglichen Spaziergang weniger Stress habe.</strong>","tag":"Family 6, experience","en":"I have found that I have less stress with my daily walk."},{"de":"<strong>In meinem Heimatland ist das Essen sehr scharf, und wir kochen fast jeden Tag frisch.</strong>","tag":"Family 6, home country","en":"In my home country the food is very spicy, and we cook fresh almost every day."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}],"B":[{"de":"<strong>Es geht um das Thema</strong> „Essen“.","tag":"Opener 1","en":"The topic is \"food\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> ein junger Mann, <strong>dass</strong> er mittags mit den Kollegen in der Kantine isst.","tag":"Opener 2","en":"On my task sheet a young man says that he eats in the canteen with his colleagues at lunchtime."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> man dort in Gesellschaft isst und nicht selbst kochen muss.","tag":"Opener 3","en":"I find this opinion interesting, because you eat in company there and do not have to cook yourself."},{"de":"<strong>Meiner Meinung nach ist Gesundheit wichtiger als alles andere.</strong>","tag":"Family 6, opinion","en":"In my opinion health is more important than anything else."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass ich mit dem täglichen Spaziergang weniger Stress habe.</strong>","tag":"Family 6, experience","en":"I have found that I have less stress with my daily walk."},{"de":"<strong>In meinem Heimatland ist das Essen sehr scharf, und wir kochen fast jeden Tag frisch.</strong>","tag":"Family 6, home country","en":"In my home country the food is very spicy, and we cook fresh almost every day."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}]}},{"no":12,"title":"Heiraten/ Hochzeit","A":{"who":"Marie Ode, 28 Jahre alt, Sekretärin","text":"Eine große Hochzeitsfeier wünsche ich mir schon immer, weil meine eigene Hochzeit der schönste Tag im Leben werden soll. Mein Mann und ich haben geplant, in 3 Tagen eine unvergessliche Party mit mehr als 70 Gästen veranstaltet."},"B":{"who":"Martin, 43 Jahre, Informatiker","text":"Seit 8 Jahren wohne ich mit meiner Partnerin. Die Hochzeitsfeier spielt für uns keine wichtige Rolle. Wir gühlen uns noch immer wohl. Auch in Zukunft planen wir keine Hochzeit."},"en":"Getting married / wedding","sol":{"A":[{"de":"<strong>Es geht um das Thema</strong> „Heiraten / Hochzeit“.","tag":"Opener 1","en":"The topic is \"getting married / wedding\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> eine junge Frau, <strong>dass</strong> sie eine große Hochzeit mit mehr als 70 Gästen feiern möchte.","tag":"Opener 2","en":"On my task sheet a young woman says that she wants to celebrate a big wedding with more than 70 guests."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> die Hochzeit für viele Menschen der schönste Tag im Leben ist.","tag":"Opener 3","en":"I find this opinion interesting, because the wedding is the most beautiful day of their life for many people."},{"de":"<strong>Meiner Meinung nach ist die Familie wichtiger als Geld oder Karriere.</strong>","tag":"Family 2, opinion","en":"In my opinion family is more important than money or career."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass man mit zwei Kindern viel Hilfe von der Familie braucht.</strong>","tag":"Family 2, experience","en":"I have found that with two children you need a lot of help from the family."},{"de":"<strong>In meinem Heimatland feiern wir oft mit der ganzen Familie, manchmal mit über hundert Gästen.</strong>","tag":"Family 2, home country","en":"In my home country we often celebrate with the whole family, sometimes with over a hundred guests."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}],"B":[{"de":"<strong>Es geht um das Thema</strong> „Heiraten / Hochzeit“.","tag":"Opener 1","en":"The topic is \"getting married / wedding\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> ein Mann, <strong>dass</strong> er seit acht Jahren mit seiner Partnerin zusammenlebt und nicht heiraten möchte.","tag":"Opener 2","en":"On my task sheet a man says that he has been living with his partner for eight years and does not want to marry."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> man auch ohne Hochzeit glücklich sein kann.","tag":"Opener 3","en":"I find this opinion interesting, because you can also be happy without a wedding."},{"de":"<strong>Meiner Meinung nach ist die Familie wichtiger als Geld oder Karriere.</strong>","tag":"Family 2, opinion","en":"In my opinion family is more important than money or career."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass man mit zwei Kindern viel Hilfe von der Familie braucht.</strong>","tag":"Family 2, experience","en":"I have found that with two children you need a lot of help from the family."},{"de":"<strong>In meinem Heimatland feiern wir oft mit der ganzen Familie, manchmal mit über hundert Gästen.</strong>","tag":"Family 2, home country","en":"In my home country we often celebrate with the whole family, sometimes with over a hundred guests."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}]}},{"no":13,"title":"Urlaub mit Freunden","A":{"who":"Jens Mühle, 30 Jahre alt, Ingenieur","text":"„Es wäre mir zu langweilig, den Urlaub allein zu verbringen. Deshalb mache ich immer mit meinen Freunden Urlaub. In dem Urlaub unternehmen wir sehr viel und organisieren gemeinsame Ausflüge“"},"B":{"who":"Charlotte Reppenhagen. 28 Jahre alt, Bürokauffrau","text":"Mein Mann und ich fahren nie zusammen mit Bekannten in den Urlaub. Wir mögen Ruhe und Erholung, deshalb möchten wir diese Zeit lieber zu weit genießen. Das wäre in einer Gruppe zu schwierig."},"en":"Holiday with friends","sol":{"A":[{"de":"<strong>Es geht um das Thema</strong> „Urlaub mit Freunden“.","tag":"Opener 1","en":"The topic is \"holidays with friends\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> ein junger Mann, <strong>dass</strong> er im Urlaub nicht allein sein möchte und mit Freunden Ausflüge organisiert.","tag":"Opener 2","en":"On my task sheet a young man says that he does not want to be alone on holiday and organises trips with friends."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> man gemeinsam mehr erlebt.","tag":"Opener 3","en":"I find this opinion interesting, because you experience more together."},{"de":"<strong>Meiner Meinung nach braucht jeder Mensch Zeit für seine Hobbys.</strong>","tag":"Family 4, opinion","en":"In my opinion every person needs time for their hobbies."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass ich nach einem langen Spaziergang viel entspannter bin.</strong>","tag":"Family 4, experience","en":"I have found that I am much more relaxed after a long walk."},{"de":"<strong>In meinem Heimatland verbringen viele Leute ihre Freizeit mit der Familie.</strong>","tag":"Family 4, home country","en":"In my home country many people spend their free time with their family."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}],"B":[{"de":"<strong>Es geht um das Thema</strong> „Urlaub mit Freunden“.","tag":"Opener 1","en":"The topic is \"holidays with friends\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> eine junge Frau, <strong>dass</strong> sie mit ihrem Mann lieber allein in den Urlaub fährt und Ruhe und Erholung mag.","tag":"Opener 2","en":"On my task sheet a young woman says that she prefers to go on holiday alone with her husband and likes peace and relaxation."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> man in einer Gruppe nicht immer die gleichen Wünsche hat.","tag":"Opener 3","en":"I find this opinion interesting, because in a group people do not always have the same wishes."},{"de":"<strong>Meiner Meinung nach braucht jeder Mensch Zeit für seine Hobbys.</strong>","tag":"Family 4, opinion","en":"In my opinion every person needs time for their hobbies."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass ich nach einem langen Spaziergang viel entspannter bin.</strong>","tag":"Family 4, experience","en":"I have found that I am much more relaxed after a long walk."},{"de":"<strong>In meinem Heimatland verbringen viele Leute ihre Freizeit mit der Familie.</strong>","tag":"Family 4, home country","en":"In my home country many people spend their free time with their family."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}]}},{"no":14,"title":"Fernsehen","A":{"who":"Claudia Volke, 24 Jahre, Praktikantin","text":"Ich mag Fernsehen. Am liebsten schaue ich mir Nachrichtensendungen und Dokumentationen an. Weiter sehe ich gern Filme, nur gibt es selten wirklich gute. Was mich nicht interessiert, sind die vielen Shows, Gewinnspiele und Ratesendungen und die Werbung. Aber das muss man sich ja nicht anschauen. Ich finde, das Fernsehen bietet heute eine große Programmauswahl. Es gibt so viele Sender und Programme, dass jeder etwas Interessantes finden kann"},"B":{"who":"Ramona Weber, 26 Jahre, Rezeptionistin","text":"Früher habe ich sehr viel ferngesehen . Irgendwann hatte ich sogar ein Satellitenfernsehen mit über 300 Sendern. Ich fand das interessant, aber nach einiger Zeit habe ich den Fernseher automatisch eingeschaltet, sobald ich frei hatte, egal ob mich irgendein Programm besonders interessiert hat, nur aus Langeweile. Ich habe kaum mehr gelesen, bin nicht mehr ins Kino oder Theater gegangen, wurde immer passiver. Das Fernsehen hat mich zudem immer nervöser gemacht. Letzten Monat habe ich meinen Fernseher verkauft. Nachrichten höre ich im Radio oder ich lese die Tageszeitung. Und Filme schaue ich mir im Kino an. Ohne Fernseher geht es mir besser."},"en":"Television","sol":{"A":[{"de":"<strong>Es geht um das Thema</strong> „Fernsehen“.","tag":"Opener 1","en":"The topic is \"watching TV\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> eine junge Frau, <strong>dass</strong> sie gern Nachrichten und Dokumentationen sieht und das Fernsehen viel Auswahl bietet.","tag":"Opener 2","en":"On my task sheet a young woman says that she likes watching news and documentaries and television offers a lot of choice."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> das Fernsehen viele Informationen bietet.","tag":"Opener 3","en":"I find this opinion interesting, because television offers a lot of information."},{"de":"<strong>Meiner Meinung nach ist das Handy praktisch, aber man sollte es nicht zu oft benutzen.</strong>","tag":"Family 1, opinion","en":"In my opinion the phone is practical, but you should not use it too often."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass ich ohne Handy besser schlafe und mehr Zeit für meine Familie habe.</strong>","tag":"Family 1, experience","en":"I have found that I sleep better without my phone and have more time for my family."},{"de":"<strong>In meinem Heimatland benutzen fast alle jungen Leute den ganzen Tag ihr Handy.</strong>","tag":"Family 1, home country","en":"In my home country almost all young people use their phones all day."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}],"B":[{"de":"<strong>Es geht um das Thema</strong> „Fernsehen“.","tag":"Opener 1","en":"The topic is \"watching TV\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> eine junge Frau, <strong>dass</strong> sie ihren Fernseher verkauft hat und es ihr seitdem besser geht.","tag":"Opener 2","en":"On my task sheet a young woman says that she sold her television and has felt better since."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> man vor dem Fernseher oft viel Zeit verliert.","tag":"Opener 3","en":"I find this opinion interesting, because you often lose a lot of time in front of the television."},{"de":"<strong>Meiner Meinung nach ist das Handy praktisch, aber man sollte es nicht zu oft benutzen.</strong>","tag":"Family 1, opinion","en":"In my opinion the phone is practical, but you should not use it too often."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass ich ohne Handy besser schlafe und mehr Zeit für meine Familie habe.</strong>","tag":"Family 1, experience","en":"I have found that I sleep better without my phone and have more time for my family."},{"de":"<strong>In meinem Heimatland benutzen fast alle jungen Leute den ganzen Tag ihr Handy.</strong>","tag":"Family 1, home country","en":"In my home country almost all young people use their phones all day."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}]}},{"no":15,"title":"Bücherhören","A":{"who":"Sabine Helbig, 26 Jahre, Rezeptionistin","text":"Ich lese gern. Das Lesen von Büchern hilft mir, meinen Geist zu entspannen und Stress abzubauen. Ich verbringe viel Zeit damit, Bücher zu lesen."},"B":{"who":"Jens Schneider, 24 Jahre, Praktikant","text":"Bücher hören ist besser. Ich kann jederzeit und überall Bücher hören, zum Beispiel beim Kochen, beim Sport oder bei anderen Aktivitäten. Für mich ist das Lesen relativ zeitaufwändig."},"en":"Listening to audiobooks","sol":{"A":[{"de":"<strong>Es geht um das Thema</strong> „Bücher hören“.","tag":"Opener 1","en":"The topic is \"audiobooks\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> eine junge Frau, <strong>dass</strong> sie gern Bücher liest und sich dabei entspannt.","tag":"Opener 2","en":"On my task sheet a young woman says that she likes reading books and relaxes while doing so."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> Lesen gegen Stress hilft.","tag":"Opener 3","en":"I find this opinion interesting, because reading helps against stress."},{"de":"<strong>Meiner Meinung nach ist das Handy praktisch, aber man sollte es nicht zu oft benutzen.</strong>","tag":"Family 1, opinion","en":"In my opinion the phone is practical, but you should not use it too often."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass ich ohne Handy besser schlafe und mehr Zeit für meine Familie habe.</strong>","tag":"Family 1, experience","en":"I have found that I sleep better without my phone and have more time for my family."},{"de":"<strong>In meinem Heimatland benutzen fast alle jungen Leute den ganzen Tag ihr Handy.</strong>","tag":"Family 1, home country","en":"In my home country almost all young people use their phones all day."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}],"B":[{"de":"<strong>Es geht um das Thema</strong> „Bücher hören“.","tag":"Opener 1","en":"The topic is \"audiobooks\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> ein junger Mann, <strong>dass</strong> man Bücher überall hören kann, zum Beispiel beim Kochen oder beim Sport.","tag":"Opener 2","en":"On my task sheet a young man says that you can listen to books anywhere, for example while cooking or doing sport."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> man dabei Zeit spart.","tag":"Opener 3","en":"I find this opinion interesting, because you save time that way."},{"de":"<strong>Meiner Meinung nach ist das Handy praktisch, aber man sollte es nicht zu oft benutzen.</strong>","tag":"Family 1, opinion","en":"In my opinion the phone is practical, but you should not use it too often."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass ich ohne Handy besser schlafe und mehr Zeit für meine Familie habe.</strong>","tag":"Family 1, experience","en":"I have found that I sleep better without my phone and have more time for my family."},{"de":"<strong>In meinem Heimatland benutzen fast alle jungen Leute den ganzen Tag ihr Handy.</strong>","tag":"Family 1, home country","en":"In my home country almost all young people use their phones all day."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}]}},{"no":16,"title":"Verwandtschaft","A":{"who":"Tobias Heinze, 26 Jahre, Büroangestellter","text":"Ich liebe Familienfeste! Zum Beispiel mag ich es sehr, wenn sich unsere ganzen Verwandten einmal im Jahr treffen. Dann essen, lachen und feiern wir gemeinsam. Manchmal wird sogar getanzt. Einige Verwandte von mir wohnen ja sehr weit weg. Es ist schön, sich dann wiederzusehen und Erinnerungen auszutauschen."},"B":{"who":"Marie Ode, 28 Jahre alt, Sekretärin","text":"Ich habe nicht viele Beziehungen, die meiste Zeit verbringe ich mit meinen Freunden. Besonders enge Freunde, weil sie mir in schwierigen Zeiten helfen können"},"en":"Relatives","sol":{"A":[{"de":"<strong>Es geht um das Thema</strong> „Verwandtschaft“.","tag":"Opener 1","en":"The topic is \"relatives\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> ein junger Mann, <strong>dass</strong> er Familienfeste liebt und sich einmal im Jahr mit allen Verwandten trifft.","tag":"Opener 2","en":"On my task sheet a young man says that he loves family celebrations and meets all his relatives once a year."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> man sich bei solchen Festen wiedersieht.","tag":"Opener 3","en":"I find this opinion interesting, because you see each other again at such celebrations."},{"de":"<strong>Meiner Meinung nach ist die Familie wichtiger als Geld oder Karriere.</strong>","tag":"Family 2, opinion","en":"In my opinion family is more important than money or career."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass man mit zwei Kindern viel Hilfe von der Familie braucht.</strong>","tag":"Family 2, experience","en":"I have found that with two children you need a lot of help from the family."},{"de":"<strong>In meinem Heimatland feiern wir oft mit der ganzen Familie, manchmal mit über hundert Gästen.</strong>","tag":"Family 2, home country","en":"In my home country we often celebrate with the whole family, sometimes with over a hundred guests."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}],"B":[{"de":"<strong>Es geht um das Thema</strong> „Verwandtschaft“.","tag":"Opener 1","en":"The topic is \"relatives\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> eine junge Frau, <strong>dass</strong> sie nicht viel Kontakt zu Verwandten hat und lieber Zeit mit engen Freunden verbringt.","tag":"Opener 2","en":"On my task sheet a young woman says that she does not have much contact with relatives and prefers to spend time with close friends."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> gute Freunde in schwierigen Zeiten helfen.","tag":"Opener 3","en":"I find this opinion interesting, because good friends help in difficult times."},{"de":"<strong>Meiner Meinung nach ist die Familie wichtiger als Geld oder Karriere.</strong>","tag":"Family 2, opinion","en":"In my opinion family is more important than money or career."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass man mit zwei Kindern viel Hilfe von der Familie braucht.</strong>","tag":"Family 2, experience","en":"I have found that with two children you need a lot of help from the family."},{"de":"<strong>In meinem Heimatland feiern wir oft mit der ganzen Familie, manchmal mit über hundert Gästen.</strong>","tag":"Family 2, home country","en":"In my home country we often celebrate with the whole family, sometimes with over a hundred guests."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}]}},{"no":17,"title":"Kleidung und Mode","A":{"who":"Dino Backer, 25 Jahre, Kellner","text":"Ich bin ein sehr realistischer Mensch und will nur was anziehen, was ich mir leisten kann und mich bequem macht. Natürlich sehe ich auch gern schöne Leute in modischer Kleidung, aber für diese teurere Sachen möchte ich nicht zahlen. Ich möchte mein Geld für etwas Nützliches für mich ausgeben"},"B":{"who":"Jens Schneider, 24 Jahre, Praktikantin","text":"Ich bin ein Fan von Mode. Zuhause habe ich eine Menge Modezeitschriften. Die Kleidungsstücke, die ich vor einem Monat gekauft habe, sind schon alt für mich. Jeden Monat gebe ich einen Teil von meinem Gehalt für neue Kleidung aus. Aussehen ist sehr wichtig, besonders in der heutigen Zeit. Wenn man nicht gut aussieht, hat man auch weniger Chancen sowohl im Leben als auch im Beruf."},"en":"Clothes and fashion","sol":{"A":[{"de":"<strong>Es geht um das Thema</strong> „Kleidung und Mode“.","tag":"Opener 1","en":"The topic is \"clothes and fashion\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> ein junger Mann, <strong>dass</strong> er nur bequeme Kleidung kauft, die er sich leisten kann.","tag":"Opener 2","en":"On my task sheet a young man says that he only buys comfortable clothes that he can afford."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> man sein Geld lieber für nützliche Dinge ausgeben kann.","tag":"Opener 3","en":"I find this opinion interesting, because you can rather spend your money on useful things."},{"de":"<strong>Meiner Meinung nach ist Qualität wichtiger als der Preis.</strong>","tag":"Family 5, opinion","en":"In my opinion quality is more important than the price."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass Bus und Bahn in der Stadt oft schneller sind als das Auto.</strong>","tag":"Family 5, experience","en":"I have found that buses and trains in the city are often faster than the car."},{"de":"<strong>In meinem Heimatland fahren die meisten Leute mit dem Auto oder mit dem Motorrad.</strong>","tag":"Family 5, home country","en":"In my home country most people travel by car or by motorbike."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}],"B":[{"de":"<strong>Es geht um das Thema</strong> „Kleidung und Mode“.","tag":"Opener 1","en":"The topic is \"clothes and fashion\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> eine junge Frau, <strong>dass</strong> sie ein Fan von Mode ist und jeden Monat neue Kleidung kauft.","tag":"Opener 2","en":"On my task sheet a young woman says that she is a fan of fashion and buys new clothes every month."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> man mit guter Kleidung bessere Chancen im Beruf haben kann.","tag":"Opener 3","en":"I find this opinion interesting, because you can have better chances at work with good clothes."},{"de":"<strong>Meiner Meinung nach ist Qualität wichtiger als der Preis.</strong>","tag":"Family 5, opinion","en":"In my opinion quality is more important than the price."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass Bus und Bahn in der Stadt oft schneller sind als das Auto.</strong>","tag":"Family 5, experience","en":"I have found that buses and trains in the city are often faster than the car."},{"de":"<strong>In meinem Heimatland fahren die meisten Leute mit dem Auto oder mit dem Motorrad.</strong>","tag":"Family 5, home country","en":"In my home country most people travel by car or by motorbike."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}]}},{"no":18,"title":"Wohngemeinschaft","A":{"who":"Frank, Friseur, 34 Jahre alt","text":"Früher war ich mit Freunden in der WG, allerdings hatten wir viele Meinungsverschiedenheiten, über Arbeitshaus, Müll rausbringen, Lebensmittel. Jetzt bin ich allein und genieße meine Unabhängigkeit."},"B":{"who":"Charlotte Reppenhagen. 28 Jahre alt, Bürokauffrau","text":"Ich lebe gerne in der WG, dort können wir viele Dinge miteinander teilen und um Hilfe bitten, wenn wir auf Schwierigkeiten stoßen. Wenn ich in der Zukunft heirate, habe ich vielleicht andere Gedanken."},"en":"Shared flat","tr":{"A":"Frank, 34, hairdresser: \"I used to live in a flat share with friends, but we had many disagreements about housework, taking out the rubbish and food. Now I am alone and enjoy my independence.\"","B":"Charlotte Reppenhagen, 28, office clerk: \"I like living in the flat share. There we can share many things and ask for help when we run into problems. If I marry in the future, I may think differently.\""},"sol":{"A":[{"de":"<strong>Es geht um das Thema</strong> „Wohngemeinschaft“.","tag":"Opener 1","en":"The topic is \"flat share\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> ein Mann, <strong>dass</strong> er früher in einer WG gewohnt hat. Jetzt wohnt er allein.","tag":"Opener 2","en":"On my task sheet a man says that he used to live in a flat share. Now he lives alone."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> es in einer WG oft Streit über die Hausarbeit gibt.","tag":"Opener 3","en":"I find this opinion interesting, because in a flat share there are often arguments about housework."},{"de":"<strong>Meiner Meinung nach ist eine ruhige Lage wichtiger als eine große Wohnung.</strong>","tag":"Family 3, opinion","en":"In my opinion a quiet location is more important than a big flat."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass Wohnungen in München sehr teuer sind.</strong>","tag":"Family 3, experience","en":"I have found that flats in Munich are very expensive. (Use your own city.)"},{"de":"<strong>In meinem Heimatland wohnen die Kinder meistens bei den Eltern, bis sie heiraten.</strong>","tag":"Family 3, home country","en":"In my home country children mostly live with their parents until they marry."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}],"B":[{"de":"<strong>Es geht um das Thema</strong> „Wohngemeinschaft“.","tag":"Opener 1","en":"The topic is \"flat share\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt eine junge Frau, dass</strong> sie gern in einer WG lebt.","tag":"Opener 2","en":"On my task sheet a young woman says that she likes living in a flat share."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> man in einer WG nicht allein ist.","tag":"Opener 3","en":"I find this opinion interesting, because in a flat share you are not alone."},{"de":"<strong>Meiner Meinung nach ist eine ruhige Lage wichtiger als eine große Wohnung.</strong>","tag":"Family 3, opinion","en":"In my opinion a quiet location is more important than a big flat."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass Wohnungen in München sehr teuer sind.</strong>","tag":"Family 3, experience","en":"I have found that flats in Munich are very expensive. (Use your own city.)"},{"de":"<strong>In meinem Heimatland wohnen die Kinder meistens bei den Eltern, bis sie heiraten.</strong>","tag":"Family 3, home country","en":"In my home country children mostly live with their parents until they marry."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}]}},{"no":19,"title":"Sammlungen und sammeln","A":{"who":"Carsten Martens 23 Jahre, Angestellter:","text":"In meiner Kindheit habe ich kleine Spielzeugautos gesammelt. . Aber jetzt sammle ich nichts mehr. Ich finde es anstrengend, Dinge zu sammeln. Da muss man immer nach Dingen suchen, die man noch nicht in seiner Sammlung hat und dafür auch noch ziemlich viel Geld ausgeben."},"B":{"who":"Silke Bauer, 21 Jahre Studentin","text":"Mein Hobby ist immer noch sammeln. Vor allem sammle ich Spielfiguren aus vielen berühmten Filmen. Manche Leute sagen, dass es eine Zeitverschwendung ist. Aber das finde ich nicht. Immer wenn ich eine schöne Figur gefunden habe, fühle ich mich sehr wohl, vergesse schon den Alltagsstress."},"en":"Collections and collecting","sol":{"A":[{"de":"<strong>Es geht um das Thema</strong> „Sammlungen und sammeln“.","tag":"Opener 1","en":"The topic is \"collecting things\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> ein junger Mann, <strong>dass</strong> er als Kind Spielzeugautos gesammelt hat, aber heute nichts mehr sammelt.","tag":"Opener 2","en":"On my task sheet a young man says that he collected toy cars as a child but does not collect anything any more today."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> Sammeln viel Zeit und Geld kostet.","tag":"Opener 3","en":"I find this opinion interesting, because collecting costs a lot of time and money."},{"de":"<strong>Meiner Meinung nach braucht jeder Mensch Zeit für seine Hobbys.</strong>","tag":"Family 4, opinion","en":"In my opinion every person needs time for their hobbies."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass ich nach einem langen Spaziergang viel entspannter bin.</strong>","tag":"Family 4, experience","en":"I have found that I am much more relaxed after a long walk."},{"de":"<strong>In meinem Heimatland verbringen viele Leute ihre Freizeit mit der Familie.</strong>","tag":"Family 4, home country","en":"In my home country many people spend their free time with their family."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}],"B":[{"de":"<strong>Es geht um das Thema</strong> „Sammlungen und sammeln“.","tag":"Opener 1","en":"The topic is \"collecting things\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> eine junge Frau, <strong>dass</strong> sie immer noch Spielfiguren aus bekannten Filmen sammelt.","tag":"Opener 2","en":"On my task sheet a young woman says that she still collects figures from famous films."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> ein Hobby gegen Alltagsstress helfen kann.","tag":"Opener 3","en":"I find this opinion interesting, because a hobby can help against everyday stress."},{"de":"<strong>Meiner Meinung nach braucht jeder Mensch Zeit für seine Hobbys.</strong>","tag":"Family 4, opinion","en":"In my opinion every person needs time for their hobbies."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass ich nach einem langen Spaziergang viel entspannter bin.</strong>","tag":"Family 4, experience","en":"I have found that I am much more relaxed after a long walk."},{"de":"<strong>In meinem Heimatland verbringen viele Leute ihre Freizeit mit der Familie.</strong>","tag":"Family 4, home country","en":"In my home country many people spend their free time with their family."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}]}},{"no":20,"title":"Ausziehen oder allein wohnen","A":{"who":"Carsten Daubner, 18 Jahre Auszubildender","text":"Pünktlich zu meinem Geburtstag bin ich ausgezogen. Meine Wohnung hat nur ein Zimmer, eine kleine Küche und ein Bad. Zum Glück ist sie nicht so teuer. Meine Eltern wollten eigentlich nicht, dass ich ausziehe. Sie sagten, ich solle erst meine Ausbildung beenden, aber ich habe sie überzeugt, dass ich meine Freiheit brauche. Ich möchte endlich auf eigenen Beinen stehen. Jetzt geben sie mir sogar ein bisschen Geld für die Miete."},"B":{"who":"Jenny Groh, 21 Jahre, Studentin","text":"Meine Eltern hätten nichts dagegen, dass ich ausziehe. Sie würden mir sogar das Geld für die Miete geben. Aber was soll ich alleine in einer kleinen Wohnung? Im Hause meiner Eltern habe ich doch viel mehr Platz. Hier habe ich nicht nur mein eigenes Zimmer, sondern auch den Garten und die anderen Räume. Das ist doch viel bequemer. Klar, bis zur Uni bin ich lange unterwegs. Aber meine Mutter leiht mir Ihr Auto."},"en":"Moving out or living alone","sol":{"A":[{"de":"<strong>Es geht um das Thema</strong> „Ausziehen oder bei den Eltern wohnen“.","tag":"Opener 1","en":"The topic is \"moving out or living with parents\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> ein junger Mann, <strong>dass</strong> er zu seinem 18. Geburtstag ausgezogen ist und jetzt auf eigenen Beinen steht.","tag":"Opener 2","en":"On my task sheet a young man says that he moved out on his 18th birthday and now stands on his own feet."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> junge Leute selbstständig werden möchten.","tag":"Opener 3","en":"I find this opinion interesting, because young people want to become independent."},{"de":"<strong>Meiner Meinung nach ist eine ruhige Lage wichtiger als eine große Wohnung.</strong>","tag":"Family 3, opinion","en":"In my opinion a quiet location is more important than a big flat."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass Wohnungen in München sehr teuer sind.</strong>","tag":"Family 3, experience","en":"I have found that flats in Munich are very expensive. (Use your own city.)"},{"de":"<strong>In meinem Heimatland wohnen die Kinder meistens bei den Eltern, bis sie heiraten.</strong>","tag":"Family 3, home country","en":"In my home country children mostly live with their parents until they marry."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}],"B":[{"de":"<strong>Es geht um das Thema</strong> „Ausziehen oder bei den Eltern wohnen“.","tag":"Opener 1","en":"The topic is \"moving out or living with parents\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> eine junge Frau, <strong>dass</strong> sie bei ihren Eltern wohnt und dort mehr Platz und einen Garten hat.","tag":"Opener 2","en":"On my task sheet a young woman says that she lives with her parents and has more space and a garden there."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> das Wohnen bei den Eltern oft bequemer und billiger ist.","tag":"Opener 3","en":"I find this opinion interesting, because living with your parents is often more comfortable and cheaper."},{"de":"<strong>Meiner Meinung nach ist eine ruhige Lage wichtiger als eine große Wohnung.</strong>","tag":"Family 3, opinion","en":"In my opinion a quiet location is more important than a big flat."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass Wohnungen in München sehr teuer sind.</strong>","tag":"Family 3, experience","en":"I have found that flats in Munich are very expensive. (Use your own city.)"},{"de":"<strong>In meinem Heimatland wohnen die Kinder meistens bei den Eltern, bis sie heiraten.</strong>","tag":"Family 3, home country","en":"In my home country children mostly live with their parents until they marry."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}]}},{"no":21,"title":"Geburtstag feiern","A":{"who":"Niklas Lambert, 23 Jahre, Student","text":"Ich feiere meinen Geburtstag nicht besonders. Für mich ist der Geburtstag ein Tag wie jeder andere auch. Feiern, Partys, Geschenke, das finde ich vollkommen überflüssig. Es gibt wichtigere Dinge im Leben."},"B":{"who":"Lena Reimer, 26 Jahre, Bürokauffrau","text":"Ich freue mich jedes Jahr wie ein kleines Kind auf meinen Geburtstag. An diesem Tag nehme ich mir immer frei und mache abends eine schöne Party. Meine Freunde und Familie kennen das schon. Ich finde, eine Geburtstagsfeier gehört einfach dazu."},"en":"Celebrating a birthday","sol":{"A":[{"de":"<strong>Es geht um das Thema</strong> „Geburtstag feiern“.","tag":"Opener 1","en":"The topic is \"celebrating birthdays\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> ein junger Mann, <strong>dass</strong> er seinen Geburtstag nicht feiert und Partys und Geschenke überflüssig findet.","tag":"Opener 2","en":"On my task sheet a young man says that he does not celebrate his birthday and finds parties and presents unnecessary."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> es im Leben wichtigere Dinge gibt.","tag":"Opener 3","en":"I find this opinion interesting, because there are more important things in life."},{"de":"<strong>Meiner Meinung nach ist die Familie wichtiger als Geld oder Karriere.</strong>","tag":"Family 2, opinion","en":"In my opinion family is more important than money or career."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass man mit zwei Kindern viel Hilfe von der Familie braucht.</strong>","tag":"Family 2, experience","en":"I have found that with two children you need a lot of help from the family."},{"de":"<strong>In meinem Heimatland feiern wir oft mit der ganzen Familie, manchmal mit über hundert Gästen.</strong>","tag":"Family 2, home country","en":"In my home country we often celebrate with the whole family, sometimes with over a hundred guests."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}],"B":[{"de":"<strong>Es geht um das Thema</strong> „Geburtstag feiern“.","tag":"Opener 1","en":"The topic is \"celebrating birthdays\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> eine junge Frau, <strong>dass</strong> sie sich jedes Jahr auf ihre Geburtstagsparty freut.","tag":"Opener 2","en":"On my task sheet a young woman says that she looks forward to her birthday party every year."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> man an diesem Tag mit Freunden und Familie feiern kann.","tag":"Opener 3","en":"I find this opinion interesting, because you can celebrate with friends and family on that day."},{"de":"<strong>Meiner Meinung nach ist die Familie wichtiger als Geld oder Karriere.</strong>","tag":"Family 2, opinion","en":"In my opinion family is more important than money or career."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass man mit zwei Kindern viel Hilfe von der Familie braucht.</strong>","tag":"Family 2, experience","en":"I have found that with two children you need a lot of help from the family."},{"de":"<strong>In meinem Heimatland feiern wir oft mit der ganzen Familie, manchmal mit über hundert Gästen.</strong>","tag":"Family 2, home country","en":"In my home country we often celebrate with the whole family, sometimes with over a hundred guests."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}]}},{"no":22,"title":"Essen kochen","A":{"who":"Martina Jahn, 34 Jahre, Arzthelferin","text":"Kochen ist meine Leidenschaft! Ich liebe es, neue Rezepte auszuprobieren und besitze eine Sammlung von Rezeptbüchern. Ich stehe stundenlang am Herd und zauberte leckere Gerichte für meine Familie - und natürlich auch für mich!"},"B":{"who":"Julian Berger, 35 Jahre, Informatiker","text":"Ich koche selten. Ich lebe allein, da lohnt es sich nicht, sich die Mühe zu machen. Außerdem macht es mir nicht so viel Spa8, in der Küche zu stehen. Wenn ich mal richtig gut essen möchte, gehe ich in mein Lieblingsrestaurant."},"en":"Cooking","sol":{"A":[{"de":"<strong>Es geht um das Thema</strong> „Essen kochen“.","tag":"Opener 1","en":"The topic is \"cooking\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> eine Frau, <strong>dass</strong> Kochen ihre Leidenschaft ist und sie gern neue Rezepte ausprobiert.","tag":"Opener 2","en":"On my task sheet a woman says that cooking is her passion and she likes trying new recipes."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> man mit Kochen der Familie eine Freude macht.","tag":"Opener 3","en":"I find this opinion interesting, because you make your family happy with cooking."},{"de":"<strong>Meiner Meinung nach ist Gesundheit wichtiger als alles andere.</strong>","tag":"Family 6, opinion","en":"In my opinion health is more important than anything else."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass ich mit dem täglichen Spaziergang weniger Stress habe.</strong>","tag":"Family 6, experience","en":"I have found that I have less stress with my daily walk."},{"de":"<strong>In meinem Heimatland ist das Essen sehr scharf, und wir kochen fast jeden Tag frisch.</strong>","tag":"Family 6, home country","en":"In my home country the food is very spicy, and we cook fresh almost every day."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}],"B":[{"de":"<strong>Es geht um das Thema</strong> „Essen kochen“.","tag":"Opener 1","en":"The topic is \"cooking\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> ein Mann, <strong>dass</strong> er selten kocht und lieber im Restaurant isst.","tag":"Opener 2","en":"On my task sheet a man says that he rarely cooks and prefers to eat in a restaurant."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> sich Kochen für eine Person oft nicht lohnt.","tag":"Opener 3","en":"I find this opinion interesting, because cooking is often not worth it for one person."},{"de":"<strong>Meiner Meinung nach ist Gesundheit wichtiger als alles andere.</strong>","tag":"Family 6, opinion","en":"In my opinion health is more important than anything else."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass ich mit dem täglichen Spaziergang weniger Stress habe.</strong>","tag":"Family 6, experience","en":"I have found that I have less stress with my daily walk."},{"de":"<strong>In meinem Heimatland ist das Essen sehr scharf, und wir kochen fast jeden Tag frisch.</strong>","tag":"Family 6, home country","en":"In my home country the food is very spicy, and we cook fresh almost every day."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}]}},{"no":23,"title":"Der ideale Urlaub","A":{"who":"Katrin Wolf, 35 Jahre, Chemikerin","text":"Ich möchte mich im Urlaub entspannen. Stundenlang Strand liegen und ein gutes Buch lesen, schön essen gehen oder einfach nur gar nichts tun. Meine Arbeit ist anstrengend genug.Da brauche ich im Urlaub viel Erholung."},"B":{"who":"Torsten Frankenberger, 40 Jahre, Busfahrer","text":"Ich will im Urlaub viel Sport machen. Ausflüge unternehmen und Neues entdecken. Für mich ist ein Abenteuerurlaub der ideale Urlaub. Langweilen kann ich mich ja, wenn ich wieder zu Hause bin."},"en":"The ideal holiday","tr":{"A":"Katrin Wolf, 35, chemist: \"I want to relax on holiday. Lie on the beach for hours and read a good book, go out for a nice meal or simply do nothing at all. My work is tiring enough. So I need a lot of rest on holiday.\"","B":"Torsten Frankenberger, 40, bus driver: \"I want to do a lot of sport on holiday, go on trips and discover new things. For me an adventure holiday is the ideal holiday. I can be bored when I am back home.\""},"sol":{"A":[{"de":"<strong>Es geht um das Thema</strong> „Der ideale Urlaub“.","tag":"Opener 1","en":"The topic is \"the ideal holiday\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> eine Frau, <strong>dass</strong> sie sich im Urlaub entspannen möchte. Sie liegt gern am Strand und liest ein Buch.","tag":"Opener 2","en":"On my task sheet a woman says that she wants to relax on holiday. She likes lying on the beach and reading a book."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> viele Menschen eine anstrengende Arbeit haben.","tag":"Opener 3","en":"I find this opinion interesting, because many people have a tiring job."},{"de":"<strong>Meiner Meinung nach braucht jeder Mensch Zeit für seine Hobbys.</strong>","tag":"Family 4, opinion","en":"In my opinion every person needs time for their hobbies."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass ich nach einem Wochenende in den Bergen viel entspannter bin.</strong>","tag":"Family 4, experience","en":"I have found that I am much more relaxed after a weekend in the mountains."},{"de":"<strong>In meinem Heimatland verbringen viele Leute ihre Freizeit mit der Familie.</strong>","tag":"Family 4, home country","en":"In my home country many people spend their free time with their family."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}],"B":[{"de":"<strong>Es geht um das Thema</strong> „Der ideale Urlaub“.","tag":"Opener 1","en":"The topic is \"the ideal holiday\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> ein Mann, <strong>dass</strong> er im Urlaub viel Sport machen und Neues entdecken will.","tag":"Opener 2","en":"On my task sheet a man says that he wants to do a lot of sport on holiday and discover new things."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> man im Urlaub viel Neues sehen kann.","tag":"Opener 3","en":"I find this opinion interesting, because on holiday you can see a lot of new things."},{"de":"<strong>Meiner Meinung nach braucht jeder Mensch Zeit für seine Hobbys.</strong>","tag":"Family 4, opinion","en":"In my opinion every person needs time for their hobbies."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass ich nach einem Wochenende in den Bergen viel entspannter bin.</strong>","tag":"Family 4, experience","en":"I have found that I am much more relaxed after a weekend in the mountains."},{"de":"<strong>In meinem Heimatland verbringen viele Leute ihre Freizeit mit der Familie.</strong>","tag":"Family 4, home country","en":"In my home country many people spend their free time with their family."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}]}},{"no":24,"title":"Haustier","A":{"who":"Udo Franke (39), Betriebswirt","text":"Haustiere sind wichtig für Kinder. Ein Hund zum Beispiel kann ein guter Freund sein. Vor allem für Kinder, die sich oft allein fühlen oder schüchtern sind, ist das eine große Hilfe. Und mit Tieren lernen Kinder, sich um jemanden zu kümmern."},"B":{"who":"Saskia Vorbeck (35), Grafikerin","text":"Unser Sohn, Timo, wünscht sich einen Hund. Doch Timo ist erst sieben Jahre alt. Wir denken, dass er zu jung ist. Ein Hund macht viel Arbeit. Man muss ihn regelmäßig füttern und mit ihm spazieren gehen. Kindern fehlt aber die nötige Disziplin."},"en":"Pets","sol":{"A":[{"de":"<strong>Es geht um das Thema</strong> „Haustier“.","tag":"Opener 1","en":"The topic is \"pets\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> ein Mann, <strong>dass</strong> Haustiere für Kinder wichtig sind.","tag":"Opener 2","en":"On my task sheet a man says that pets are important for children."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> Kinder mit einem Tier lernen, Verantwortung zu übernehmen.","tag":"Opener 3","en":"I find this opinion interesting, because children learn to take responsibility with an animal."},{"de":"<strong>Meiner Meinung nach braucht jeder Mensch Zeit für seine Hobbys.</strong>","tag":"Family 4, opinion","en":"In my opinion every person needs time for their hobbies."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass ich nach einem langen Spaziergang viel entspannter bin.</strong>","tag":"Family 4, experience","en":"I have found that I am much more relaxed after a long walk."},{"de":"<strong>In meinem Heimatland verbringen viele Leute ihre Freizeit mit der Familie.</strong>","tag":"Family 4, home country","en":"In my home country many people spend their free time with their family."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}],"B":[{"de":"<strong>Es geht um das Thema</strong> „Haustier“.","tag":"Opener 1","en":"The topic is \"pets\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> eine Frau, <strong>dass</strong> ihr siebenjähriger Sohn noch zu jung für einen Hund ist.","tag":"Opener 2","en":"On my task sheet a woman says that her seven-year-old son is still too young for a dog."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> ein Hund viel Arbeit macht.","tag":"Opener 3","en":"I find this opinion interesting, because a dog is a lot of work."},{"de":"<strong>Meiner Meinung nach braucht jeder Mensch Zeit für seine Hobbys.</strong>","tag":"Family 4, opinion","en":"In my opinion every person needs time for their hobbies."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass ich nach einem langen Spaziergang viel entspannter bin.</strong>","tag":"Family 4, experience","en":"I have found that I am much more relaxed after a long walk."},{"de":"<strong>In meinem Heimatland verbringen viele Leute ihre Freizeit mit der Familie.</strong>","tag":"Family 4, home country","en":"In my home country many people spend their free time with their family."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}]}},{"no":25,"title":"Gastfreundschaft","A":{"who":"Karins Ferbeck, 34 Jahre, Lehrerin","text":"Ich bin nicht gern allein, daher freue ich mich über jeden Gast, der mich besucht.Ich habe extra ein Gästezimmer eingerichtet, damit Freunde und Verwandte bei mir übernachten können."},"B":{"who":"Niklas Weber, 34 Jahre, Informatiker","text":"Ich lade eigentlich selten Gäste zu mir nach Hause ein. Kochen, sich um die Gäste kümmern und so weiter - das ist mir zu anstrengend! Und Überraschungsbesuche hasse ich ganz besonders!"},"en":"Hospitality","sol":{"A":[{"de":"<strong>Es geht um das Thema</strong> „Gastfreundschaft“.","tag":"Opener 1","en":"The topic is \"hospitality\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> eine Frau, <strong>dass</strong> sie sich über jeden Gast freut und extra ein Gästezimmer eingerichtet hat.","tag":"Opener 2","en":"On my task sheet a woman says that she is happy about every guest and has even set up a guest room."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> Besuch das Zuhause lebendig macht.","tag":"Opener 3","en":"I find this opinion interesting, because visitors make a home lively."},{"de":"<strong>Meiner Meinung nach ist die Familie wichtiger als Geld oder Karriere.</strong>","tag":"Family 2, opinion","en":"In my opinion family is more important than money or career."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass man mit zwei Kindern viel Hilfe von der Familie braucht.</strong>","tag":"Family 2, experience","en":"I have found that with two children you need a lot of help from the family."},{"de":"<strong>In meinem Heimatland feiern wir oft mit der ganzen Familie, manchmal mit über hundert Gästen.</strong>","tag":"Family 2, home country","en":"In my home country we often celebrate with the whole family, sometimes with over a hundred guests."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}],"B":[{"de":"<strong>Es geht um das Thema</strong> „Gastfreundschaft“.","tag":"Opener 1","en":"The topic is \"hospitality\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> ein Mann, <strong>dass</strong> er selten Gäste einlädt und Überraschungsbesuche nicht mag.","tag":"Opener 2","en":"On my task sheet a man says that he rarely invites guests and does not like surprise visits."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> Gäste zu bewirten anstrengend sein kann.","tag":"Opener 3","en":"I find this opinion interesting, because hosting guests can be tiring."},{"de":"<strong>Meiner Meinung nach ist die Familie wichtiger als Geld oder Karriere.</strong>","tag":"Family 2, opinion","en":"In my opinion family is more important than money or career."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass man mit zwei Kindern viel Hilfe von der Familie braucht.</strong>","tag":"Family 2, experience","en":"I have found that with two children you need a lot of help from the family."},{"de":"<strong>In meinem Heimatland feiern wir oft mit der ganzen Familie, manchmal mit über hundert Gästen.</strong>","tag":"Family 2, home country","en":"In my home country we often celebrate with the whole family, sometimes with over a hundred guests."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}]}},{"no":26,"title":"Auto Kaufen","A":{"who":"Sabine Pfister, 38 Jahre, Industriekauffrau","text":"Ich möchte mir bald ein neues Auto kaufen: Ich habe schon lange dafür Geld gespart und möchte mir nun diesen Traum erfüllen. Für mich ist ein Auto mehr als nur ein Fahrzeug. Es ist auch ein Stück Lebensstil."},"B":{"who":"Wegmann Karl, 40 Jahre, Verkäufer","text":"Derzeit ist meine Familie jeden Tag mit dem Motorrad unterwegs. Autos sind für uns eine teure Sache. Wir müssen jeden Monat viel Geld für Reparaturen ausgeben. Wir werden das überdenken, wenn wir in der Zukunft ein höheres Einkommen haben."},"en":"Buying a car","sol":{"A":[{"de":"<strong>Es geht um das Thema</strong> „Auto kaufen“.","tag":"Opener 1","en":"The topic is \"buying a car\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> eine Frau, <strong>dass</strong> sie sich bald ein neues Auto kaufen möchte.","tag":"Opener 2","en":"On my task sheet a woman says that she wants to buy a new car soon."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> ein Auto für viele Menschen mehr als nur ein Fahrzeug ist.","tag":"Opener 3","en":"I find this opinion interesting, because a car is more than just a vehicle for many people."},{"de":"<strong>Meiner Meinung nach ist Qualität wichtiger als der Preis.</strong>","tag":"Family 5, opinion","en":"In my opinion quality is more important than the price."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass Bus und Bahn in der Stadt oft schneller sind als das Auto.</strong>","tag":"Family 5, experience","en":"I have found that buses and trains in the city are often faster than the car."},{"de":"<strong>In meinem Heimatland fahren die meisten Leute mit dem Auto oder mit dem Motorrad.</strong>","tag":"Family 5, home country","en":"In my home country most people travel by car or by motorbike."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}],"B":[{"de":"<strong>Es geht um das Thema</strong> „Auto kaufen“.","tag":"Opener 1","en":"The topic is \"buying a car\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> ein Mann, <strong>dass</strong> seine Familie mit dem Motorrad fährt und ein Auto zu teuer findet.","tag":"Opener 2","en":"On my task sheet a man says that his family rides a motorbike and finds a car too expensive."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> ein Auto viel Geld für Reparaturen kostet.","tag":"Opener 3","en":"I find this opinion interesting, because a car costs a lot of money for repairs."},{"de":"<strong>Meiner Meinung nach ist Qualität wichtiger als der Preis.</strong>","tag":"Family 5, opinion","en":"In my opinion quality is more important than the price."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass Bus und Bahn in der Stadt oft schneller sind als das Auto.</strong>","tag":"Family 5, experience","en":"I have found that buses and trains in the city are often faster than the car."},{"de":"<strong>In meinem Heimatland fahren die meisten Leute mit dem Auto oder mit dem Motorrad.</strong>","tag":"Family 5, home country","en":"In my home country most people travel by car or by motorbike."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}]}},{"no":27,"title":"Nachbarn","A":{"who":"Enna Streif, 24 Jahre, Büroangestellte","text":"Bei uns im Haus wohnen so viele Leute, dass ich gar nicht alle Nachbarn kennen kann. Außerdem bin ich vor wenigen Wochen neu eingezogen und kenne hier niemanden. Ich wohne allein. Leider gibt es oft Streit zwischen Nachbarn, daher bin ich froh, wenn ich meine Ruhe habe."},"B":{"who":"Christ Gebhardt, 21 Jahre, Büroangestellter","text":"Ich verstehe mich sehr gut mit meinen Nachbarn. Sie sind ungefähr so alt wie ich. Manchmal machen wir kleine Partys und besuchen uns gegenseitig. Ein Nachbar hat mir auch schon oft geholfen, denn er ist Handwerker und kann viele Reparaturen machen."},"en":"Neighbours","sol":{"A":[{"de":"<strong>Es geht um das Thema</strong> „Nachbarn“.","tag":"Opener 1","en":"The topic is \"neighbours\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> eine junge Frau, <strong>dass</strong> sie neu eingezogen ist und ihre Nachbarn nicht kennt.","tag":"Opener 2","en":"On my task sheet a young woman says that she has just moved in and does not know her neighbours."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> es zwischen Nachbarn oft Streit gibt.","tag":"Opener 3","en":"I find this opinion interesting, because there are often arguments between neighbours."},{"de":"<strong>Meiner Meinung nach ist eine ruhige Lage wichtiger als eine große Wohnung.</strong>","tag":"Family 3, opinion","en":"In my opinion a quiet location is more important than a big flat."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass Wohnungen in München sehr teuer sind.</strong>","tag":"Family 3, experience","en":"I have found that flats in Munich are very expensive. (Use your own city.)"},{"de":"<strong>In meinem Heimatland wohnen die Kinder meistens bei den Eltern, bis sie heiraten.</strong>","tag":"Family 3, home country","en":"In my home country children mostly live with their parents until they marry."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}],"B":[{"de":"<strong>Es geht um das Thema</strong> „Nachbarn“.","tag":"Opener 1","en":"The topic is \"neighbours\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> ein junger Mann, <strong>dass</strong> er sich gut mit seinen Nachbarn versteht und sie sich gegenseitig helfen.","tag":"Opener 2","en":"On my task sheet a young man says that he gets on well with his neighbours and they help each other."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> gute Nachbarn das Leben leichter machen.","tag":"Opener 3","en":"I find this opinion interesting, because good neighbours make life easier."},{"de":"<strong>Meiner Meinung nach ist eine ruhige Lage wichtiger als eine große Wohnung.</strong>","tag":"Family 3, opinion","en":"In my opinion a quiet location is more important than a big flat."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass Wohnungen in München sehr teuer sind.</strong>","tag":"Family 3, experience","en":"I have found that flats in Munich are very expensive. (Use your own city.)"},{"de":"<strong>In meinem Heimatland wohnen die Kinder meistens bei den Eltern, bis sie heiraten.</strong>","tag":"Family 3, home country","en":"In my home country children mostly live with their parents until they marry."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}]}},{"no":28,"title":"Kinder im Freizeitstress - Ehrgeizig Eltern","A":{"who":"Marie Baumann, 37 Jahre, Hausfrau","text":"Wir haben unseren Sohn gefragt, ob er im Verein Sport machen möchte. Er hatte da keine Lust, wollte aber unbedingt “einen Malkurs” machen. Nun besucht er seit drei Jahren immer wieder Zeichen- und Malkurse und das macht ihm sehr viel Spaß. Für Sport interessiert er sich nicht."},"B":{"who":"Volker Diestel, 35 Jahre, Autohändler","text":"Wir wollten, dass unsere Tochter zwei Musikinstrumente lernt und auch Sport im Verein macht. Jetzt lernt sie Schlagzeug und macht Leichtathletik. Vielleicht fängt sie bald mit der Gitarre an. Das würde uns sehr gefallen."},"en":"Children with a stressful free time: ambitious parents","sol":{"A":[{"de":"<strong>Es geht um das Thema</strong> „Kinder im Freizeitstress / ehrgeizige Eltern“.","tag":"Opener 1","en":"The topic is \"busy children / ambitious parents\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> eine Frau, <strong>dass</strong> ihr Sohn lieber zum Malkurs geht als zum Sport.","tag":"Opener 2","en":"On my task sheet a woman says that her son prefers going to a painting class to doing sport."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> Kinder selbst entscheiden sollten, was sie gern machen.","tag":"Opener 3","en":"I find this opinion interesting, because children should decide for themselves what they like doing."},{"de":"<strong>Meiner Meinung nach ist die Familie wichtiger als Geld oder Karriere.</strong>","tag":"Family 2, opinion","en":"In my opinion family is more important than money or career."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass man mit zwei Kindern viel Hilfe von der Familie braucht.</strong>","tag":"Family 2, experience","en":"I have found that with two children you need a lot of help from the family."},{"de":"<strong>In meinem Heimatland feiern wir oft mit der ganzen Familie, manchmal mit über hundert Gästen.</strong>","tag":"Family 2, home country","en":"In my home country we often celebrate with the whole family, sometimes with over a hundred guests."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}],"B":[{"de":"<strong>Es geht um das Thema</strong> „Kinder im Freizeitstress / ehrgeizige Eltern“.","tag":"Opener 1","en":"The topic is \"busy children / ambitious parents\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> ein Mann, <strong>dass</strong> seine Tochter zwei Instrumente lernt und Sport im Verein macht.","tag":"Opener 2","en":"On my task sheet a man says that his daughter learns two instruments and does sport in a club."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> Kinder viele Möglichkeiten brauchen, aber nicht zu viel Stress haben sollten.","tag":"Opener 3","en":"I find this opinion interesting, because children need many opportunities but should not have too much stress."},{"de":"<strong>Meiner Meinung nach ist die Familie wichtiger als Geld oder Karriere.</strong>","tag":"Family 2, opinion","en":"In my opinion family is more important than money or career."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass man mit zwei Kindern viel Hilfe von der Familie braucht.</strong>","tag":"Family 2, experience","en":"I have found that with two children you need a lot of help from the family."},{"de":"<strong>In meinem Heimatland feiern wir oft mit der ganzen Familie, manchmal mit über hundert Gästen.</strong>","tag":"Family 2, home country","en":"In my home country we often celebrate with the whole family, sometimes with over a hundred guests."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}]}},{"no":29,"title":"Großeltern","A":{"who":"Melissa Junghans, 23 Jahre, Studentin","text":"Ich habe meine Großeltern leider nie kennengelernt. Gerne habe ich mit ihnen über ihre Kindheit und unsere Familiengeschichte gesprochen. Ich hatte ihnen auch viele Fragen gestellt"},"B":{"who":"Michael Schmidt, 32 Jahre, Manager","text":"Ich sehe meine Großeltern nur selten. Sie sind schon älter und erzählen immer die gleichen Geschichten von früheren Zeiten. Das finde ich langweilig. Aber so ist das eben. Manche Menschen in diesem Alter leben einfach in einer anderen Welt."},"en":"Grandparents","sol":{"A":[{"de":"<strong>Es geht um das Thema</strong> „Großeltern“.","tag":"Opener 1","en":"The topic is \"grandparents\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> eine junge Frau, <strong>dass</strong> sie ihre Großeltern nie kennengelernt hat und gern mit ihnen gesprochen hätte.","tag":"Opener 2","en":"On my task sheet a young woman says that she never met her grandparents and would have liked to talk to them."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> Großeltern viel aus der Familiengeschichte erzählen können.","tag":"Opener 3","en":"I find this opinion interesting, because grandparents can tell a lot about the family history."},{"de":"<strong>Meiner Meinung nach ist die Familie wichtiger als Geld oder Karriere.</strong>","tag":"Family 2, opinion","en":"In my opinion family is more important than money or career."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass man mit zwei Kindern viel Hilfe von der Familie braucht.</strong>","tag":"Family 2, experience","en":"I have found that with two children you need a lot of help from the family."},{"de":"<strong>In meinem Heimatland feiern wir oft mit der ganzen Familie, manchmal mit über hundert Gästen.</strong>","tag":"Family 2, home country","en":"In my home country we often celebrate with the whole family, sometimes with over a hundred guests."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}],"B":[{"de":"<strong>Es geht um das Thema</strong> „Großeltern“.","tag":"Opener 1","en":"The topic is \"grandparents\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> ein Mann, <strong>dass</strong> er seine Großeltern nur selten sieht und ihre Geschichten langweilig findet.","tag":"Opener 2","en":"On my task sheet a man says that he only rarely sees his grandparents and finds their stories boring."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> ältere Menschen oft in einer anderen Welt leben.","tag":"Opener 3","en":"I find this opinion interesting, because older people often live in a different world."},{"de":"<strong>Meiner Meinung nach ist die Familie wichtiger als Geld oder Karriere.</strong>","tag":"Family 2, opinion","en":"In my opinion family is more important than money or career."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass man mit zwei Kindern viel Hilfe von der Familie braucht.</strong>","tag":"Family 2, experience","en":"I have found that with two children you need a lot of help from the family."},{"de":"<strong>In meinem Heimatland feiern wir oft mit der ganzen Familie, manchmal mit über hundert Gästen.</strong>","tag":"Family 2, home country","en":"In my home country we often celebrate with the whole family, sometimes with over a hundred guests."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}]}},{"no":30,"title":"Allein wohnen","A":{"who":"Era Dorn, 35 Jahre, Kosmetikerin","text":"Ich lebe gern allein. So kann ich tun und lassen, was ich will. Niemand mischt sich in meine Angelegenheiten ein. Wenn ich mich mal einsam fühle, treffe ich mich mit Freunden oder besuche meine Eltern."},"B":{"who":"Bernd Mannsfeldt, 42 Jahre, Malermeister","text":"Ich kann mir nicht vorstellen, allein zu leben. Das wäre mir zu langweilig! Ich lebe mit meiner Frau, unseren drei Kindern, meinem Schwiegervater zusammen. Da ist immer was los, aber das ist auch gut so. CÁC ĐỀ ĐANG RA HAY THI"},"en":"Living alone","sol":{"A":[{"de":"<strong>Es geht um das Thema</strong> „Allein wohnen“.","tag":"Opener 1","en":"The topic is \"living alone\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> eine Frau, <strong>dass</strong> sie gern allein lebt und tun kann, was sie will.","tag":"Opener 2","en":"On my task sheet a woman says that she likes living alone and can do what she wants."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> man allein sehr unabhängig ist.","tag":"Opener 3","en":"I find this opinion interesting, because you are very independent when you live alone."},{"de":"<strong>Meiner Meinung nach ist eine ruhige Lage wichtiger als eine große Wohnung.</strong>","tag":"Family 3, opinion","en":"In my opinion a quiet location is more important than a big flat."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass Wohnungen in München sehr teuer sind.</strong>","tag":"Family 3, experience","en":"I have found that flats in Munich are very expensive. (Use your own city.)"},{"de":"<strong>In meinem Heimatland wohnen die Kinder meistens bei den Eltern, bis sie heiraten.</strong>","tag":"Family 3, home country","en":"In my home country children mostly live with their parents until they marry."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}],"B":[{"de":"<strong>Es geht um das Thema</strong> „Allein wohnen“.","tag":"Opener 1","en":"The topic is \"living alone\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> ein Mann, <strong>dass</strong> er nicht allein leben könnte und mit seiner großen Familie zusammenwohnt.","tag":"Opener 2","en":"On my task sheet a man says that he could not live alone and lives together with his big family."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> in einer großen Familie immer etwas los ist.","tag":"Opener 3","en":"I find this opinion interesting, because there is always something going on in a big family."},{"de":"<strong>Meiner Meinung nach ist eine ruhige Lage wichtiger als eine große Wohnung.</strong>","tag":"Family 3, opinion","en":"In my opinion a quiet location is more important than a big flat."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass Wohnungen in München sehr teuer sind.</strong>","tag":"Family 3, experience","en":"I have found that flats in Munich are very expensive. (Use your own city.)"},{"de":"<strong>In meinem Heimatland wohnen die Kinder meistens bei den Eltern, bis sie heiraten.</strong>","tag":"Family 3, home country","en":"In my home country children mostly live with their parents until they marry."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}]}},{"no":31,"title":"Brief oder E-mail","A":{"who":"Harald Haubner, 29 Jahre, Kaufmann","text":"Ich finde es schade, dass viele Menschen nicht mit der Hand schreiben wollen. Also ich freue mich immer über einen handgeschrieben Brief oder eine Karte, zum Beispiel zum Geburtstag. Das ist viel persönlicher als eine E-mail oder eine Nachricht am Telefon."},"B":{"who":"Tina Klein, 35 Jahre, Pflegerin","text":"Briefe schreibe ich nie. Wozu auch? Es dauert viel zu lange, bis ein Brief endlich ankommt. Eine E-Mail oder eine Nachricht per Telefon ist sofort beim Empfänger. Da kann ich auch Emojis benutzen. Briefe finde ich altmodisch."},"en":"Letter or e-mail","tr":{"A":"Harald Haubner, 29, businessman: \"I think it is a pity that many people do not want to write by hand. I am always happy about a handwritten letter or a card, for example for my birthday. That is much more personal than an e-mail or a message on the phone.\"","B":"Tina Klein, 35, nurse: \"I never write letters. Why would I? It takes far too long until a letter finally arrives. An e-mail or a phone message reaches the receiver at once. I can also use emojis there. I find letters old- fashioned.\""},"sol":{"A":[{"de":"<strong>Es geht um das Thema</strong> „Brief oder E-Mail“.","tag":"Opener 1","en":"The topic is \"letter or e-mail\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> ein junger Mann, <strong>dass</strong> er sich über einen handgeschriebenen Brief freut.","tag":"Opener 2","en":"On my task sheet a young man says that he is happy about a handwritten letter."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> ein Brief viel persönlicher ist.","tag":"Opener 3","en":"I find this opinion interesting, because a letter is much more personal."},{"de":"<strong>Meiner Meinung nach ist das Handy praktisch, aber man sollte es nicht zu oft benutzen.</strong>","tag":"Family 1, opinion","en":"In my opinion the phone is practical, but you should not use it too often."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass ich ohne Handy besser schlafe und mehr Zeit für meine Familie habe.</strong>","tag":"Family 1, experience","en":"I have found that I sleep better without my phone and have more time for my family."},{"de":"<strong>In meinem Heimatland benutzen fast alle jungen Leute den ganzen Tag ihr Handy.</strong>","tag":"Family 1, home country","en":"In my home country almost all young people use their phones all day."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}],"B":[{"de":"<strong>Es geht um das Thema</strong> „Brief oder E-Mail“.","tag":"Opener 1","en":"The topic is \"letter or e-mail\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> eine Frau, <strong>dass</strong> sie nie Briefe schreibt.","tag":"Opener 2","en":"On my task sheet a woman says that she never writes letters."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> eine E-Mail sofort ankommt.","tag":"Opener 3","en":"I find this opinion interesting, because an e-mail arrives at once."},{"de":"<strong>Meiner Meinung nach ist das Handy praktisch, aber man sollte es nicht zu oft benutzen.</strong>","tag":"Family 1, opinion","en":"In my opinion the phone is practical, but you should not use it too often."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass ich ohne Handy besser schlafe und mehr Zeit für meine Familie habe.</strong>","tag":"Family 1, experience","en":"I have found that I sleep better without my phone and have more time for my family."},{"de":"<strong>In meinem Heimatland benutzen fast alle jungen Leute den ganzen Tag ihr Handy.</strong>","tag":"Family 1, home country","en":"In my home country almost all young people use their phones all day."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}]}},{"no":32,"title":"Smartphone in der Schule","A":{"who":"Ann-Marie Hübner , 39 Jahre, Lehrerin","text":"Ich bin Lehrerin und nutze das Smartphone oft. Es ist wirklich hilfreich, wenn man sofort eine Information im Internet findet. Meine Schüler dürfen es auch im Unterricht benutzen, dann finden sie zum Beispiel Filme, Bilder, und Musik des Themas, das wir gerade behandeln. Das macht ihnen Spaß."},"B":{"who":"Christin Bergner , 41 Jahre, Mechatroniker","text":"Meine Kinder sind den ganzen Tag am Smartphone und das nervt mich. Sie müssen doch nicht auch noch in der Schule damit spielen. Außerdem finde ich, dass man mit einem Smartphone sowieso nicht lernen kann. Sobald eine Nachricht kommt, konzentrieren sie sich nicht mehr auf den Unterricht."},"en":"Smartphones at school","sol":{"A":[{"de":"<strong>Es geht um das Thema</strong> „Smartphone in der Schule“.","tag":"Opener 1","en":"The topic is \"smartphones at school\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> eine Frau, <strong>dass</strong> sie das Smartphone im Unterricht nutzt und ihre Schüler damit Informationen finden.","tag":"Opener 2","en":"On my task sheet a woman says that she uses the smartphone in class and her pupils find information with it."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> Schüler so mit mehr Spaß lernen.","tag":"Opener 3","en":"I find this opinion interesting, because pupils learn with more fun that way."},{"de":"<strong>Meiner Meinung nach ist das Handy praktisch, aber man sollte es nicht zu oft benutzen.</strong>","tag":"Family 1, opinion","en":"In my opinion the phone is practical, but you should not use it too often."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass ich ohne Handy besser schlafe und mehr Zeit für meine Familie habe.</strong>","tag":"Family 1, experience","en":"I have found that I sleep better without my phone and have more time for my family."},{"de":"<strong>In meinem Heimatland benutzen fast alle jungen Leute den ganzen Tag ihr Handy.</strong>","tag":"Family 1, home country","en":"In my home country almost all young people use their phones all day."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}],"B":[{"de":"<strong>Es geht um das Thema</strong> „Smartphone in der Schule“.","tag":"Opener 1","en":"The topic is \"smartphones at school\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> eine Person, <strong>dass</strong> ihre Kinder schon den ganzen Tag am Smartphone sind und in der Schule nicht damit spielen sollen.","tag":"Opener 2","en":"On my task sheet a person says that their children are on their smartphones all day already and should not play with them at school as well."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> Nachrichten die Schüler vom Unterricht ablenken.","tag":"Opener 3","en":"I find this opinion interesting, because messages distract the pupils from the lesson."},{"de":"<strong>Meiner Meinung nach ist das Handy praktisch, aber man sollte es nicht zu oft benutzen.</strong>","tag":"Family 1, opinion","en":"In my opinion the phone is practical, but you should not use it too often."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass ich ohne Handy besser schlafe und mehr Zeit für meine Familie habe.</strong>","tag":"Family 1, experience","en":"I have found that I sleep better without my phone and have more time for my family."},{"de":"<strong>In meinem Heimatland benutzen fast alle jungen Leute den ganzen Tag ihr Handy.</strong>","tag":"Family 1, home country","en":"In my home country almost all young people use their phones all day."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}]}},{"no":33,"title":"Handynutzung in öffentlichen Verkehrsmitteln","A":{"who":"Anna Beckmann, 20 Jahre, Studentin","text":"Beim täglichen Pendeln mit Bus und Bahn ist mein Smartphone ein unverzichtbarer Begleiter. Ich nutze es, um Nachrichten zu schreiben, Musik zu hören und mit Lern-Apps die Fahrzeit sinnvoll zu nutzen. So wird jede Fahrt nicht nur angenehmer, sondern auch produktiver. Dank moderner Technik kann ich unterwegs flexibel und vernetzt leben."},"B":{"who":"Oliver Schneider, 75 Jahre, Rentner","text":"Früher schätzte ich die Fahrten mit Bus und Bahn sehr - die ruhige Atmosphäre und die Gespräche mit anderen Fahrgästen waren etwas Besonderes. Heute ist das anders: Überall höre ich laute Musik oder Telefonate, und die meisten Menschen starren nur auf ihre Handys. Selbst in Gruppen spricht kaum noch jemand miteinander. \"Ich finde das wirklich schade.\""},"en":"Using mobile phones on public transport","sol":{"A":[{"de":"<strong>Es geht um das Thema</strong> „Handynutzung in öffentlichen Verkehrsmitteln“.","tag":"Opener 1","en":"The topic is \"phones on public transport\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> eine junge Frau, <strong>dass</strong> sie in Bus und Bahn Nachrichten schreibt, Musik hört und lernt.","tag":"Opener 2","en":"On my task sheet a young woman says that she writes messages, listens to music and studies on the bus and train."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> man die Fahrzeit so gut nutzen kann.","tag":"Opener 3","en":"I find this opinion interesting, because you can use the travel time well that way."},{"de":"<strong>Meiner Meinung nach ist das Handy praktisch, aber man sollte es nicht zu oft benutzen.</strong>","tag":"Family 1, opinion","en":"In my opinion the phone is practical, but you should not use it too often."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass ich ohne Handy besser schlafe und mehr Zeit für meine Familie habe.</strong>","tag":"Family 1, experience","en":"I have found that I sleep better without my phone and have more time for my family."},{"de":"<strong>In meinem Heimatland benutzen fast alle jungen Leute den ganzen Tag ihr Handy.</strong>","tag":"Family 1, home country","en":"In my home country almost all young people use their phones all day."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}],"B":[{"de":"<strong>Es geht um das Thema</strong> „Handynutzung in öffentlichen Verkehrsmitteln“.","tag":"Opener 1","en":"The topic is \"phones on public transport\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> ein älterer Mann, <strong>dass</strong> in Bus und Bahn fast alle nur auf ihr Handy schauen und kaum noch jemand spricht.","tag":"Opener 2","en":"On my task sheet an older man says that on buses and trains almost everybody only looks at their phone and hardly anybody talks any more."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> Gespräche früher für eine ruhige, angenehme Atmosphäre gesorgt haben.","tag":"Opener 3","en":"I find this opinion interesting, because conversations used to create a calm, pleasant atmosphere."},{"de":"<strong>Meiner Meinung nach ist das Handy praktisch, aber man sollte es nicht zu oft benutzen.</strong>","tag":"Family 1, opinion","en":"In my opinion the phone is practical, but you should not use it too often."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass ich ohne Handy besser schlafe und mehr Zeit für meine Familie habe.</strong>","tag":"Family 1, experience","en":"I have found that I sleep better without my phone and have more time for my family."},{"de":"<strong>In meinem Heimatland benutzen fast alle jungen Leute den ganzen Tag ihr Handy.</strong>","tag":"Family 1, home country","en":"In my home country almost all young people use their phones all day."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}]}},{"no":34,"title":"Im Internet bestellen","A":{"who":"Heike Bittner (36), Hausfrau","text":"Am liebsten bestelle ich meine Kleider im Internet. Die Auswahl ist viel größer als im Laden. Überfüllte Geschäfte mag ich nicht. Ich suche lieber zu Hause aus und probiere dann in aller Ruhe. Was mir nicht gefällt, kann ich problemlos zurückschicken."},"B":{"who":"Carlo Marchese (33), Malermeister","text":"Ich kaufe nicht oft Kleidung. Aber wenn ich etwas brauche, nehme ich mir Zeit und gehe in die Stadt. Im Internet bestellen mag ich nicht. Die Farben sind oft ganz anders als auf den Fotos. Der Stoff sieht auf den Bildern auch meistens besser aus."},"en":"Ordering on the internet","sol":{"A":[{"de":"<strong>Es geht um das Thema</strong> „Im Internet bestellen“.","tag":"Opener 1","en":"The topic is \"ordering online\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> eine Frau, <strong>dass</strong> sie ihre Kleidung am liebsten im Internet bestellt.","tag":"Opener 2","en":"On my task sheet a woman says that she likes ordering her clothes online best."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> die Auswahl groß ist und man Sachen zurückschicken kann.","tag":"Opener 3","en":"I find this opinion interesting, because the choice is big and you can send things back."},{"de":"<strong>Meiner Meinung nach ist das Handy praktisch, aber man sollte es nicht zu oft benutzen.</strong>","tag":"Family 1, opinion","en":"In my opinion the phone is practical, but you should not use it too often."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass ich ohne Handy besser schlafe und mehr Zeit für meine Familie habe.</strong>","tag":"Family 1, experience","en":"I have found that I sleep better without my phone and have more time for my family."},{"de":"<strong>In meinem Heimatland benutzen fast alle jungen Leute den ganzen Tag ihr Handy.</strong>","tag":"Family 1, home country","en":"In my home country almost all young people use their phones all day."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}],"B":[{"de":"<strong>Es geht um das Thema</strong> „Im Internet bestellen“.","tag":"Opener 1","en":"The topic is \"ordering online\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> ein Mann, <strong>dass</strong> er Kleidung lieber im Geschäft kauft und nicht im Internet bestellt.","tag":"Opener 2","en":"On my task sheet a man says that he prefers to buy clothes in a shop and does not order them online."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> die Farben auf den Fotos oft anders aussehen.","tag":"Opener 3","en":"I find this opinion interesting, because the colours often look different in the photos."},{"de":"<strong>Meiner Meinung nach ist das Handy praktisch, aber man sollte es nicht zu oft benutzen.</strong>","tag":"Family 1, opinion","en":"In my opinion the phone is practical, but you should not use it too often."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass ich ohne Handy besser schlafe und mehr Zeit für meine Familie habe.</strong>","tag":"Family 1, experience","en":"I have found that I sleep better without my phone and have more time for my family."},{"de":"<strong>In meinem Heimatland benutzen fast alle jungen Leute den ganzen Tag ihr Handy.</strong>","tag":"Family 1, home country","en":"In my home country almost all young people use their phones all day."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}]}},{"no":35,"title":"Gemeinschaftsgarten","A":{"who":"Lisa Feldmann (43), Kamerafrau","text":"Wir nutzen seit einem Jahr ein Stück in einem Gemeinschaftsgarten. Wir bauen Gemüse und Kräuter an. So wissen wir, wo unser Essen herkommt. Wir können ganz sicher sein, dass es wirklich Bio ist. Außerdem macht uns die Arbeit im Freien viel Freude."},"B":{"who":"Harald Dauber (29), Kaufmann","text":"Meine Eltern sind Mieter in einem Gemeinschaftsgarten. Da gibt es oft Stress: zum Beispiel, wenn es lange nicht regnet, und die teuren Pflanzen vertrocknen. Wenn sie in Urlaub fahren wollen, muss jemand den Garten für sie gießen. Ich kaufe mein Gemüse lieber im Laden."},"en":"Community garden","sol":{"A":[{"de":"<strong>Es geht um das Thema</strong> „Gemeinschaftsgarten“.","tag":"Opener 1","en":"The topic is \"community garden\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> eine Frau, <strong>dass</strong> sie mit ihrer Familie Gemüse und Kräuter in einem Gemeinschaftsgarten anbaut.","tag":"Opener 2","en":"On my task sheet a woman says that she grows vegetables and herbs with her family in a community garden."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> man so weiß, woher das Essen kommt.","tag":"Opener 3","en":"I find this opinion interesting, because you know where the food comes from that way."},{"de":"<strong>Meiner Meinung nach ist eine ruhige Lage wichtiger als eine große Wohnung.</strong>","tag":"Family 3, opinion","en":"In my opinion a quiet location is more important than a big flat."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass Wohnungen in München sehr teuer sind.</strong>","tag":"Family 3, experience","en":"I have found that flats in Munich are very expensive. (Use your own city.)"},{"de":"<strong>In meinem Heimatland wohnen die Kinder meistens bei den Eltern, bis sie heiraten.</strong>","tag":"Family 3, home country","en":"In my home country children mostly live with their parents until they marry."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}],"B":[{"de":"<strong>Es geht um das Thema</strong> „Gemeinschaftsgarten“.","tag":"Opener 1","en":"The topic is \"community garden\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> ein junger Mann, <strong>dass</strong> seine Eltern im Gemeinschaftsgarten oft Stress haben und er sein Gemüse lieber im Laden kauft.","tag":"Opener 2","en":"On my task sheet a young man says that his parents often have stress in the community garden and he prefers to buy his vegetables in the shop."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> ein Garten viel Arbeit macht.","tag":"Opener 3","en":"I find this opinion interesting, because a garden is a lot of work."},{"de":"<strong>Meiner Meinung nach ist eine ruhige Lage wichtiger als eine große Wohnung.</strong>","tag":"Family 3, opinion","en":"In my opinion a quiet location is more important than a big flat."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass Wohnungen in München sehr teuer sind.</strong>","tag":"Family 3, experience","en":"I have found that flats in Munich are very expensive. (Use your own city.)"},{"de":"<strong>In meinem Heimatland wohnen die Kinder meistens bei den Eltern, bis sie heiraten.</strong>","tag":"Family 3, home country","en":"In my home country children mostly live with their parents until they marry."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}]}},{"no":36,"title":"Tiktok","A":{"who":"Mandy Heuser, 43 Jahre, Designerin","text":"Unsere Tochter postet regelmäßig Videos auf TikTok. Anfangs habe ich mir Sorgen gemacht. Aber nun sehe ich, wie gut es ihr tut. Sie hat wirklich Talent als Schauspielerin und Sängerin, und das kann sie so mit anderen teilen. Ihre Videos haben viel Erfolg."},"B":{"who":"Kevin , 34 Jahre, Autohändler","text":"Manche Menschen verbringen Stunden mit TikTok-Videos. Das ist doch reine Zeitverschwendung. Warum sollten einem die Darstellungen und Meinungen fremder Leute wichtig sein? Ich würde mir lieber ein schönes Hobby suchen. Es gibt so viele Möglichkeiten."},"en":"TikTok","sol":{"A":[{"de":"<strong>Es geht um das Thema</strong> „TikTok“.","tag":"Opener 1","en":"The topic is \"TikTok\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> eine Frau, <strong>dass</strong> ihre Tochter Videos auf TikTok postet und damit Erfolg hat.","tag":"Opener 2","en":"On my task sheet a woman says that her daughter posts videos on TikTok and is successful with them."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> junge Leute dort ihr Talent zeigen können.","tag":"Opener 3","en":"I find this opinion interesting, because young people can show their talent there."},{"de":"<strong>Meiner Meinung nach ist das Handy praktisch, aber man sollte es nicht zu oft benutzen.</strong>","tag":"Family 1, opinion","en":"In my opinion the phone is practical, but you should not use it too often."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass ich ohne Handy besser schlafe und mehr Zeit für meine Familie habe.</strong>","tag":"Family 1, experience","en":"I have found that I sleep better without my phone and have more time for my family."},{"de":"<strong>In meinem Heimatland benutzen fast alle jungen Leute den ganzen Tag ihr Handy.</strong>","tag":"Family 1, home country","en":"In my home country almost all young people use their phones all day."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}],"B":[{"de":"<strong>Es geht um das Thema</strong> „TikTok“.","tag":"Opener 1","en":"The topic is \"TikTok\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> ein Mann, <strong>dass</strong> TikTok reine Zeitverschwendung ist.","tag":"Opener 2","en":"On my task sheet a man says that TikTok is a pure waste of time."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> man seine Zeit besser für ein Hobby nutzen kann.","tag":"Opener 3","en":"I find this opinion interesting, because you can use your time better for a hobby."},{"de":"<strong>Meiner Meinung nach ist das Handy praktisch, aber man sollte es nicht zu oft benutzen.</strong>","tag":"Family 1, opinion","en":"In my opinion the phone is practical, but you should not use it too often."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass ich ohne Handy besser schlafe und mehr Zeit für meine Familie habe.</strong>","tag":"Family 1, experience","en":"I have found that I sleep better without my phone and have more time for my family."},{"de":"<strong>In meinem Heimatland benutzen fast alle jungen Leute den ganzen Tag ihr Handy.</strong>","tag":"Family 1, home country","en":"In my home country almost all young people use their phones all day."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}]}},{"no":37,"title":"Große Feier veranstalten","A":{"who":"Christin Bergner, 41 Jahre, Mechatroniker","text":"Unsere Großmutter feiert bald ihren 80. Geburtstag. Wir feiern bei uns im Garten, das passt gut für unsere große Familie. Die Kinder haben Platz zum Spielen. Seit Wochen überlegen wir, wer was kochen soll. Es gibt viel zu tun, aber es macht auch Spaß!"},"B":{"who":"Sybille Sauer, 43 Jahre, Designerin","text":"Gestern haben wir den 50. Hochzeitstag unserer Eltern gefeiert. Wir waren in einem Restaurant. So mussten wir uns nicht um die Vorbereitung kümmern. Nur das Menü hatten wir schon vorbestellt. Die Kinder haben sich ein bisschen gelangweilt, aber den Erwachsenen hat es gut gefallen."},"en":"Holding a big party","sol":{"A":[{"de":"<strong>Es geht um das Thema</strong> „Eine große Feier veranstalten“.","tag":"Opener 1","en":"The topic is \"organising a big party\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> eine Person, <strong>dass</strong> ihre Familie den 80. Geburtstag der Großmutter im Garten feiert.","tag":"Opener 2","en":"On my task sheet a person says that their family is celebrating grandmother's 80th birthday in the garden."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> bei einem Fest im Garten die ganze Familie Platz hat.","tag":"Opener 3","en":"I find this opinion interesting, because there is room for the whole family at a party in the garden."},{"de":"<strong>Meiner Meinung nach ist die Familie wichtiger als Geld oder Karriere.</strong>","tag":"Family 2, opinion","en":"In my opinion family is more important than money or career."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass man mit zwei Kindern viel Hilfe von der Familie braucht.</strong>","tag":"Family 2, experience","en":"I have found that with two children you need a lot of help from the family."},{"de":"<strong>In meinem Heimatland feiern wir oft mit der ganzen Familie, manchmal mit über hundert Gästen.</strong>","tag":"Family 2, home country","en":"In my home country we often celebrate with the whole family, sometimes with over a hundred guests."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}],"B":[{"de":"<strong>Es geht um das Thema</strong> „Eine große Feier veranstalten“.","tag":"Opener 1","en":"The topic is \"organising a big party\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> eine Frau, <strong>dass</strong> ihre Familie den 50. Hochzeitstag der Eltern im Restaurant gefeiert hat.","tag":"Opener 2","en":"On my task sheet a woman says that her family celebrated her parents' 50th wedding anniversary in a restaurant."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> man im Restaurant nichts vorbereiten muss.","tag":"Opener 3","en":"I find this opinion interesting, because you do not have to prepare anything in a restaurant."},{"de":"<strong>Meiner Meinung nach ist die Familie wichtiger als Geld oder Karriere.</strong>","tag":"Family 2, opinion","en":"In my opinion family is more important than money or career."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass man mit zwei Kindern viel Hilfe von der Familie braucht.</strong>","tag":"Family 2, experience","en":"I have found that with two children you need a lot of help from the family."},{"de":"<strong>In meinem Heimatland feiern wir oft mit der ganzen Familie, manchmal mit über hundert Gästen.</strong>","tag":"Family 2, home country","en":"In my home country we often celebrate with the whole family, sometimes with over a hundred guests."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}]}},{"no":38,"title":"Öffentlichen Verkehrsmittel","A":{"who":"Carola Ahrenholz, 25 Jahre, Sekretärin","text":"Im Sommer fahre ich immer mit dem Fahrrad zur Arbeit. Dann komme ich morgens schon munter ins Büro und abends kann ich mich beim Fahren wunderbar entspannen. Nur wenn es regnet, nehme ich den Bus. Im Winter fahre ich immer mit einer Kollegin im Auto. Dafür gebe ich ihr etwas Benzingeld, so sparen wir beide und tun außerdem noch etwas für den Umweltschutz."},"B":{"who":"Bernd Kleinefeld, 45 Jahre, Elektrotechniker","text":"Mein Auto brauche ich am meisten für meine Freizeitaktivitäten: Am Wochenende machen wir Ausflüge, unter der Woche fahre ich in die Stadt, ins Kino oder zum Sport. Um zur Arbeit zu kommen, benutze ich auch das Auto. Und weil wir auf dem Land wohnen, muss ich ziemlich oft auch die Kinder irgendwohin bringen."},"en":"Public transport","sol":{"A":[{"de":"<strong>Es geht um das Thema</strong> „Öffentliche Verkehrsmittel“.","tag":"Opener 1","en":"The topic is \"public transport\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> eine junge Frau, <strong>dass</strong> sie im Sommer mit dem Fahrrad zur Arbeit fährt und im Winter mit einer Kollegin im Auto.","tag":"Opener 2","en":"On my task sheet a young woman says that she cycles to work in summer and goes by car with a colleague in winter."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> man so Geld spart und etwas für die Umwelt tut.","tag":"Opener 3","en":"I find this opinion interesting, because you save money and do something for the environment that way."},{"de":"<strong>Meiner Meinung nach ist Qualität wichtiger als der Preis.</strong>","tag":"Family 5, opinion","en":"In my opinion quality is more important than the price."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass Bus und Bahn in der Stadt oft schneller sind als das Auto.</strong>","tag":"Family 5, experience","en":"I have found that buses and trains in the city are often faster than the car."},{"de":"<strong>In meinem Heimatland fahren die meisten Leute mit dem Auto oder mit dem Motorrad.</strong>","tag":"Family 5, home country","en":"In my home country most people travel by car or by motorbike."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}],"B":[{"de":"<strong>Es geht um das Thema</strong> „Öffentliche Verkehrsmittel“.","tag":"Opener 1","en":"The topic is \"public transport\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> ein Mann, <strong>dass</strong> er mit dem Auto zur Arbeit fährt und auch seine Kinder damit bringt.","tag":"Opener 2","en":"On my task sheet a man says that he drives to work by car and also takes his children by car."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> man auf dem Land ohne Auto kaum mobil ist.","tag":"Opener 3","en":"I find this opinion interesting, because in the countryside you are hardly mobile without a car."},{"de":"<strong>Meiner Meinung nach ist Qualität wichtiger als der Preis.</strong>","tag":"Family 5, opinion","en":"In my opinion quality is more important than the price."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass Bus und Bahn in der Stadt oft schneller sind als das Auto.</strong>","tag":"Family 5, experience","en":"I have found that buses and trains in the city are often faster than the car."},{"de":"<strong>In meinem Heimatland fahren die meisten Leute mit dem Auto oder mit dem Motorrad.</strong>","tag":"Family 5, home country","en":"In my home country most people travel by car or by motorbike."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}]}},{"no":39,"title":"Gemeinsame Mahlzeiten","A":{"who":"Stefan Wilkens, (41), Ingenieur","text":"Gemeinsame Mahlzeiten sind sehr wichtig in unserer Familie. Wir helfen alle beim Kochen. Mindestens einmal am Tag, meistens abends, sitzen wir alle um den großen Tisch, essen und erzählen uns gegenseitig, was am Tag so los war. Beim Essen fällt das Erzählen leicht."},"B":{"who":"Heike Bittner, (36), Hausfrau","text":"Mein Mann und ich arbeiten und unser Sohn studiert. So hat jeder seinen eigenen Rhythmus, und wir sitzen fast nie zusammen an einem Tisch. Ich finde das in Ordnung. So ist das eben in unserer Zeit."},"en":"Meals together","sol":{"A":[{"de":"<strong>Es geht um das Thema</strong> „Gemeinsame Mahlzeiten“.","tag":"Opener 1","en":"The topic is \"shared meals\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> ein Mann, <strong>dass</strong> seine Familie mindestens einmal am Tag gemeinsam isst und zusammen kocht.","tag":"Opener 2","en":"On my task sheet a man says that his family eats together at least once a day and cooks together."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> man beim Essen leicht miteinander ins Gespräch kommt.","tag":"Opener 3","en":"I find this opinion interesting, because it is easy to start a conversation while eating."},{"de":"<strong>Meiner Meinung nach ist Gesundheit wichtiger als alles andere.</strong>","tag":"Family 6, opinion","en":"In my opinion health is more important than anything else."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass ich mit dem täglichen Spaziergang weniger Stress habe.</strong>","tag":"Family 6, experience","en":"I have found that I have less stress with my daily walk."},{"de":"<strong>In meinem Heimatland ist das Essen sehr scharf, und wir kochen fast jeden Tag frisch.</strong>","tag":"Family 6, home country","en":"In my home country the food is very spicy, and we cook fresh almost every day."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}],"B":[{"de":"<strong>Es geht um das Thema</strong> „Gemeinsame Mahlzeiten“.","tag":"Opener 1","en":"The topic is \"shared meals\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> eine Frau, <strong>dass</strong> in ihrer Familie jeder seinen eigenen Rhythmus hat und man fast nie zusammen isst.","tag":"Opener 2","en":"On my task sheet a woman says that in her family everybody has their own rhythm and they almost never eat together."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> viele Familien wegen der Arbeit keine Zeit haben.","tag":"Opener 3","en":"I find this opinion interesting, because many families have no time because of work."},{"de":"<strong>Meiner Meinung nach ist Gesundheit wichtiger als alles andere.</strong>","tag":"Family 6, opinion","en":"In my opinion health is more important than anything else."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass ich mit dem täglichen Spaziergang weniger Stress habe.</strong>","tag":"Family 6, experience","en":"I have found that I have less stress with my daily walk."},{"de":"<strong>In meinem Heimatland ist das Essen sehr scharf, und wir kochen fast jeden Tag frisch.</strong>","tag":"Family 6, home country","en":"In my home country the food is very spicy, and we cook fresh almost every day."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}]}},{"no":40,"title":"Serie oder Film","A":{"who":"Steffi, 29 Jahre alt, Redakteurin","text":"Also, ich bin richtig süchtig nach Serien! Am Wochenende streame ich manchmal stundenlang, eine Folge nach der anderen. Zwischendurch schreibe ich mit meinen Freundinnen, und wir diskutieren über die Geschichte oder über unsere Lieblingsschauspieler."},"B":{"who":"Heike Bittner, 36 Jahre alt, Hausfrau","text":"Serien streamen interessiert mich überhaupt nicht. Mehrere Folgen anschauen, das wird mir zu viel. So lange will ich nicht vor dem Bildschirm sitzen. Aber ich möchte auch nicht eine ganze Woche auf die nächste Folge warten. Ein Film mit einer abgeschlossenen Geschichte, das ist mir lieber."},"en":"Series or film","sol":{"A":[{"de":"<strong>Es geht um das Thema</strong> „Serie oder Film“.","tag":"Opener 1","en":"The topic is \"series or film\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> eine junge Frau, <strong>dass</strong> sie am Wochenende stundenlang Serien streamt.","tag":"Opener 2","en":"On my task sheet a young woman says that she streams series for hours at the weekend."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> man mit Freundinnen über die Geschichte diskutieren kann.","tag":"Opener 3","en":"I find this opinion interesting, because you can discuss the story with friends."},{"de":"<strong>Meiner Meinung nach ist das Handy praktisch, aber man sollte es nicht zu oft benutzen.</strong>","tag":"Family 1, opinion","en":"In my opinion the phone is practical, but you should not use it too often."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass ich ohne Handy besser schlafe und mehr Zeit für meine Familie habe.</strong>","tag":"Family 1, experience","en":"I have found that I sleep better without my phone and have more time for my family."},{"de":"<strong>In meinem Heimatland benutzen fast alle jungen Leute den ganzen Tag ihr Handy.</strong>","tag":"Family 1, home country","en":"In my home country almost all young people use their phones all day."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}],"B":[{"de":"<strong>Es geht um das Thema</strong> „Serie oder Film“.","tag":"Opener 1","en":"The topic is \"series or film\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> eine Frau, <strong>dass</strong> sie lieber einen Film mit abgeschlossener Geschichte sieht als Serien.","tag":"Opener 2","en":"On my task sheet a woman says that she prefers watching a film with a complete story to series."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> man bei einem Film nicht auf die nächste Folge warten muss.","tag":"Opener 3","en":"I find this opinion interesting, because with a film you do not have to wait for the next episode."},{"de":"<strong>Meiner Meinung nach ist das Handy praktisch, aber man sollte es nicht zu oft benutzen.</strong>","tag":"Family 1, opinion","en":"In my opinion the phone is practical, but you should not use it too often."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass ich ohne Handy besser schlafe und mehr Zeit für meine Familie habe.</strong>","tag":"Family 1, experience","en":"I have found that I sleep better without my phone and have more time for my family."},{"de":"<strong>In meinem Heimatland benutzen fast alle jungen Leute den ganzen Tag ihr Handy.</strong>","tag":"Family 1, home country","en":"In my home country almost all young people use their phones all day."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}]}},{"no":41,"title":"Bauernmarkt","A":{"who":"Eva Winter, 37 Jahre, Lehrerin","text":"Ich kaufe meistens am Samstag auf dem Bauernmarkt ein. Dort bekomme ich frisches Gemüse aus der Umgebung. Es gibt auch Brot und sogar Biofleisch. Im Supermarkt kommt alles aus der Fabrik und schmeckt nicht so gut. Außerdem unterstütze ich mit meinem Einkauf die kleinen Bauernbetriebe."},"B":{"who":"Tobias Meier, 40 Jahre, Informatiker","text":"Ich gehe selten auf den Bauernmarkt. Ich habe nicht viel Zeit, also kaufe ich meine Lebensmittel lieber im Supermarkt. Dort finde ich alles an einem Ort, und es ist oft billiger. Natürlich ist frisches Gemüse vom Bauernmarkt besser, aber für mich ist es einfach praktischer, schnell im Supermarkt einzukaufen."},"en":"Farmers' market","sol":{"A":[{"de":"<strong>Es geht um das Thema</strong> „Bauernmarkt“.","tag":"Opener 1","en":"The topic is \"farmers’ market\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> eine Frau, <strong>dass</strong> sie samstags auf dem Bauernmarkt frisches Gemüse kauft.","tag":"Opener 2","en":"On my task sheet a woman says that she buys fresh vegetables at the farmers' market on Saturdays."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> man damit kleine Bauernbetriebe unterstützt.","tag":"Opener 3","en":"I find this opinion interesting, because you support small farms with it."},{"de":"<strong>Meiner Meinung nach ist Gesundheit wichtiger als alles andere.</strong>","tag":"Family 6, opinion","en":"In my opinion health is more important than anything else."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass ich mit dem täglichen Spaziergang weniger Stress habe.</strong>","tag":"Family 6, experience","en":"I have found that I have less stress with my daily walk."},{"de":"<strong>In meinem Heimatland ist das Essen sehr scharf, und wir kochen fast jeden Tag frisch.</strong>","tag":"Family 6, home country","en":"In my home country the food is very spicy, and we cook fresh almost every day."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}],"B":[{"de":"<strong>Es geht um das Thema</strong> „Bauernmarkt“.","tag":"Opener 1","en":"The topic is \"farmers’ market\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> ein Mann, <strong>dass</strong> er wenig Zeit hat und lieber im Supermarkt einkauft.","tag":"Opener 2","en":"On my task sheet a man says that he has little time and prefers shopping in the supermarket."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> man im Supermarkt alles an einem Ort findet.","tag":"Opener 3","en":"I find this opinion interesting, because you find everything in one place in the supermarket."},{"de":"<strong>Meiner Meinung nach ist Gesundheit wichtiger als alles andere.</strong>","tag":"Family 6, opinion","en":"In my opinion health is more important than anything else."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass ich mit dem täglichen Spaziergang weniger Stress habe.</strong>","tag":"Family 6, experience","en":"I have found that I have less stress with my daily walk."},{"de":"<strong>In meinem Heimatland ist das Essen sehr scharf, und wir kochen fast jeden Tag frisch.</strong>","tag":"Family 6, home country","en":"In my home country the food is very spicy, and we cook fresh almost every day."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}]}},{"no":42,"title":"Umzug","A":{"who":"","text":"Hassan al-Amiri, Malerson Ich bin sehr oft umgezogen. In der Regel alle vier bis fünf Jahre. Immer in einer neuen Umgebung mit neuen Nachbarn. Das hat mir immer gutgetan. Ich halte es einfach nicht sehr lange an einem Ort aus, denn ich brauche die Veränderung."},"B":{"who":"","text":"Sabine Igel, Floristin Wir - mein Mann und ich - haben uns vor Kurzem ein Haus gekauft. Wir wollten nicht mehr Mieter sein und wir hatten auch keine Lust mehr auf Umzüge. Wir wohnen jetzt auf dem Land und fühlen uns dort sehr wohl. Zu unseren Nachbarn haben wir ein freundschaftliches Verhältnis. Also, vermutlich werden wir nie wieder umziehen."},"en":"Moving house","sol":{"A":[{"de":"<strong>Es geht um das Thema</strong> „Umzug“.","tag":"Opener 1","en":"The topic is \"moving house\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> ein Mann, <strong>dass</strong> er sehr oft umgezogen ist und die Veränderung braucht.","tag":"Opener 2","en":"On my task sheet a man says that he has moved very often and needs the change."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> eine neue Umgebung vielen Menschen guttut.","tag":"Opener 3","en":"I find this opinion interesting, because a new environment is good for many people."},{"de":"<strong>Meiner Meinung nach ist eine ruhige Lage wichtiger als eine große Wohnung.</strong>","tag":"Family 3, opinion","en":"In my opinion a quiet location is more important than a big flat."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass Wohnungen in München sehr teuer sind.</strong>","tag":"Family 3, experience","en":"I have found that flats in Munich are very expensive. (Use your own city.)"},{"de":"<strong>In meinem Heimatland wohnen die Kinder meistens bei den Eltern, bis sie heiraten.</strong>","tag":"Family 3, home country","en":"In my home country children mostly live with their parents until they marry."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}],"B":[{"de":"<strong>Es geht um das Thema</strong> „Umzug“.","tag":"Opener 1","en":"The topic is \"moving house\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> eine Frau, <strong>dass</strong> sie mit ihrem Mann ein Haus gekauft hat und nicht mehr umziehen möchte.","tag":"Opener 2","en":"On my task sheet a woman says that she and her husband bought a house and do not want to move again."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> man in einem eigenen Haus zur Ruhe kommt.","tag":"Opener 3","en":"I find this opinion interesting, because you can settle down in a house of your own."},{"de":"<strong>Meiner Meinung nach ist eine ruhige Lage wichtiger als eine große Wohnung.</strong>","tag":"Family 3, opinion","en":"In my opinion a quiet location is more important than a big flat."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass Wohnungen in München sehr teuer sind.</strong>","tag":"Family 3, experience","en":"I have found that flats in Munich are very expensive. (Use your own city.)"},{"de":"<strong>In meinem Heimatland wohnen die Kinder meistens bei den Eltern, bis sie heiraten.</strong>","tag":"Family 3, home country","en":"In my home country children mostly live with their parents until they marry."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}]}},{"no":43,"title":"Auto, oder Bus oder Bahn","A":{"who":"","text":"Birgit Krah, Köchin Ich bin so froh, dass ich ein Auto habe. Das erleichtert mir den Alltag. So bin ich sehr flexibel, kann meine Musik einschalten und von A nach B fahren. Auf dem Weg zur Arbeit oder nach Hause muss ich auch nicht laute oder nervige Menschen ertragen."},"B":{"who":"","text":"Amir Zaid, Sport- und Fitnesskaufmann Ich brauche kein Auto. Da ich in der Stadt lebe, komme ich mit der U-Bahn schnell voran. Ich muss auch keinen Parkplatz suchen. Inzwischen ist das Parken in den Städten richtig teuer geworden. So kann ich nach der Arbeit, wenn ich nach Hause fahre, entspannt sein."},"en":"Car, bus or train","sol":{"A":[{"de":"<strong>Es geht um das Thema</strong> „Auto oder Bus und Bahn“.","tag":"Opener 1","en":"The topic is \"car or bus and train\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> eine Frau, <strong>dass</strong> ein Auto ihren Alltag erleichtert und sie damit sehr flexibel ist.","tag":"Opener 2","en":"On my task sheet a woman says that a car makes her everyday life easier and she is very flexible with it."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> man im Auto seine Ruhe hat.","tag":"Opener 3","en":"I find this opinion interesting, because you have your peace in the car."},{"de":"<strong>Meiner Meinung nach ist Qualität wichtiger als der Preis.</strong>","tag":"Family 5, opinion","en":"In my opinion quality is more important than the price."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass Bus und Bahn in der Stadt oft schneller sind als das Auto.</strong>","tag":"Family 5, experience","en":"I have found that buses and trains in the city are often faster than the car."},{"de":"<strong>In meinem Heimatland fahren die meisten Leute mit dem Auto oder mit dem Motorrad.</strong>","tag":"Family 5, home country","en":"In my home country most people travel by car or by motorbike."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}],"B":[{"de":"<strong>Es geht um das Thema</strong> „Auto oder Bus und Bahn“.","tag":"Opener 1","en":"The topic is \"car or bus and train\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> ein Mann, <strong>dass</strong> er in der Stadt mit der U-Bahn schnell vorankommt und kein Auto braucht.","tag":"Opener 2","en":"On my task sheet a man says that he gets around quickly by underground in the city and does not need a car."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> Parken in der Stadt sehr teuer ist.","tag":"Opener 3","en":"I find this opinion interesting, because parking in the city is very expensive."},{"de":"<strong>Meiner Meinung nach ist Qualität wichtiger als der Preis.</strong>","tag":"Family 5, opinion","en":"In my opinion quality is more important than the price."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass Bus und Bahn in der Stadt oft schneller sind als das Auto.</strong>","tag":"Family 5, experience","en":"I have found that buses and trains in the city are often faster than the car."},{"de":"<strong>In meinem Heimatland fahren die meisten Leute mit dem Auto oder mit dem Motorrad.</strong>","tag":"Family 5, home country","en":"In my home country most people travel by car or by motorbike."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}]}},{"no":44,"title":"Smartphone","A":{"who":"Hanna Streblow (46), Trainerin","text":"Manche Kinder halten schon im Kinderwagen ein Smartphone in der Hand. Fachleute sagen aber, dass Kinder unter vier Jahren gar kein Handy haben sollen, und zwischen vier und sechs Jahren höchstens 20 bis 30 Minuten pro Tag. Das finde ich auch gut so."},"B":{"who":"Luigi Bellini, (39), Musiker","text":"Das Smartphone gehört zu unserem Leben. Deshalb sollten Kleinkinder auch so früh wie möglich lernen, damit umzugehen. Früher haben Kinder mit Holzspielzeug gespielt, heute spielen sie mit elektronischen Geräten. Was soll daran schlecht sein? Die Welt verändert sich eben."},"en":"Smartphone","sol":{"A":[{"de":"<strong>Es geht um das Thema</strong> „Smartphone“.","tag":"Opener 1","en":"The topic is \"smartphones for small children\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> eine Frau, <strong>dass</strong> Kleinkinder unter vier Jahren gar kein Handy haben sollten.","tag":"Opener 2","en":"On my task sheet a woman says that small children under four should not have a phone at all."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> Fachleute das auch empfehlen.","tag":"Opener 3","en":"I find this opinion interesting, because experts recommend that too."},{"de":"<strong>Meiner Meinung nach ist das Handy praktisch, aber man sollte es nicht zu oft benutzen.</strong>","tag":"Family 1, opinion","en":"In my opinion the phone is practical, but you should not use it too often."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass ich ohne Handy besser schlafe und mehr Zeit für meine Familie habe.</strong>","tag":"Family 1, experience","en":"I have found that I sleep better without my phone and have more time for my family."},{"de":"<strong>In meinem Heimatland benutzen fast alle jungen Leute den ganzen Tag ihr Handy.</strong>","tag":"Family 1, home country","en":"In my home country almost all young people use their phones all day."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}],"B":[{"de":"<strong>Es geht um das Thema</strong> „Smartphone“.","tag":"Opener 1","en":"The topic is \"smartphones for small children\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> ein Mann, <strong>dass</strong> Kleinkinder so früh wie möglich lernen sollten, mit dem Smartphone umzugehen.","tag":"Opener 2","en":"On my task sheet a man says that small children should learn as early as possible how to handle a smartphone."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> sich die Welt verändert und Technik zum Leben gehört.","tag":"Opener 3","en":"I find this opinion interesting, because the world is changing and technology is part of life."},{"de":"<strong>Meiner Meinung nach ist das Handy praktisch, aber man sollte es nicht zu oft benutzen.</strong>","tag":"Family 1, opinion","en":"In my opinion the phone is practical, but you should not use it too often."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass ich ohne Handy besser schlafe und mehr Zeit für meine Familie habe.</strong>","tag":"Family 1, experience","en":"I have found that I sleep better without my phone and have more time for my family."},{"de":"<strong>In meinem Heimatland benutzen fast alle jungen Leute den ganzen Tag ihr Handy.</strong>","tag":"Family 1, home country","en":"In my home country almost all young people use their phones all day."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}]}},{"no":45,"title":"Sport im Fitnessstudio","A":{"who":"","text":"Hassan al-Amiri, Maler Ich gehe regelmäßig ins Gym. Die haben so tolle Geräte und vor allem sehr gute Beratung. Wenn man zwischendurch etwas wissen möchte, ist auch immer jemand zur Stelle. Und das Gute an der Sache ist, dass Wind und Wetter keine Rolle spielen."},"B":{"who":"","text":"Kurt Baumgart, IT-System Elektroniker Das ist nichts für mich. Die Fahrt ins nächste Fitnessstudio würde mich ca. 20 Minuten kosten. Und dann müsste ich dort auch noch zusammen mit Fremden trainieren. Darauf habe ich gar keine Lust. Ich habe mir bei uns im Haus ein Sportzimmer eingerichtet. So kann ich trainieren, ohne das Haus zu verlassen."},"en":"Sport in the gym","sol":{"A":[{"de":"<strong>Es geht um das Thema</strong> „Sport im Fitnessstudio“.","tag":"Opener 1","en":"The topic is \"sport at the gym\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> ein Mann, <strong>dass</strong> er regelmäßig ins Fitnessstudio geht.","tag":"Opener 2","en":"On my task sheet a man says that he goes to the gym regularly."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> man dort gute Geräte und gute Beratung hat.","tag":"Opener 3","en":"I find this opinion interesting, because you have good equipment and good advice there."},{"de":"<strong>Meiner Meinung nach ist Gesundheit wichtiger als alles andere.</strong>","tag":"Family 6, opinion","en":"In my opinion health is more important than anything else."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass ich mit dem täglichen Spaziergang weniger Stress habe.</strong>","tag":"Family 6, experience","en":"I have found that I have less stress with my daily walk."},{"de":"<strong>In meinem Heimatland ist das Essen sehr scharf, und wir kochen fast jeden Tag frisch.</strong>","tag":"Family 6, home country","en":"In my home country the food is very spicy, and we cook fresh almost every day."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}],"B":[{"de":"<strong>Es geht um das Thema</strong> „Sport im Fitnessstudio“.","tag":"Opener 1","en":"The topic is \"sport at the gym\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> ein Mann, <strong>dass</strong> er zu Hause in einem Sportzimmer trainiert und nicht ins Fitnessstudio gehen möchte.","tag":"Opener 2","en":"On my task sheet a man says that he trains at home in a sports room and does not want to go to the gym."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> man so Zeit und den Weg spart.","tag":"Opener 3","en":"I find this opinion interesting, because you save time and the journey that way."},{"de":"<strong>Meiner Meinung nach ist Gesundheit wichtiger als alles andere.</strong>","tag":"Family 6, opinion","en":"In my opinion health is more important than anything else."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass ich mit dem täglichen Spaziergang weniger Stress habe.</strong>","tag":"Family 6, experience","en":"I have found that I have less stress with my daily walk."},{"de":"<strong>In meinem Heimatland ist das Essen sehr scharf, und wir kochen fast jeden Tag frisch.</strong>","tag":"Family 6, home country","en":"In my home country the food is very spicy, and we cook fresh almost every day."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}]}},{"no":46,"title":"Klassentreffen","A":{"who":"Steffi, 29 Jahre alt, Redakteurin","text":"Wir veranstalten jedes Jahr ein Klassentreffen. Immer am selben Ort und zur selben Zeit. Natürlich haben wir auch eine WhatsApp-Gruppe. So wissen wir immer, wer teilnehmen wird. Wir sitzen dann stundenlang zusammen und es ist immer sehr lustig. Ich freue mich jedes Jahr auf das Wiedersehen."},"B":{"who":"Heike Bittner, 36 Jahre alt, Hausfrau","text":"An meine Schulzeit denke ich nicht gern zurück. An die Mitschüler eigentlich auch nicht. Das alles liegt so lange zurück und ich habe damit abgeschlossen. Mich interessiert auch nicht, was aus den Leuten geworden ist. Und auch nicht, was sie zu erzählen haben."},"en":"Class reunion","sol":{"A":[{"de":"<strong>Es geht um das Thema</strong> „Klassentreffen“.","tag":"Opener 1","en":"The topic is \"class reunion\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> eine junge Frau, <strong>dass</strong> sie sich jedes Jahr auf das Klassentreffen freut.","tag":"Opener 2","en":"On my task sheet a young woman says that she looks forward to the class reunion every year."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> man alte Freunde wiedersieht.","tag":"Opener 3","en":"I find this opinion interesting, because you see old friends again."},{"de":"<strong>Meiner Meinung nach ist die Familie wichtiger als Geld oder Karriere.</strong>","tag":"Family 2, opinion","en":"In my opinion family is more important than money or career."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass man mit zwei Kindern viel Hilfe von der Familie braucht.</strong>","tag":"Family 2, experience","en":"I have found that with two children you need a lot of help from the family."},{"de":"<strong>In meinem Heimatland feiern wir oft mit der ganzen Familie, manchmal mit über hundert Gästen.</strong>","tag":"Family 2, home country","en":"In my home country we often celebrate with the whole family, sometimes with over a hundred guests."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}],"B":[{"de":"<strong>Es geht um das Thema</strong> „Klassentreffen“.","tag":"Opener 1","en":"The topic is \"class reunion\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> eine Frau, <strong>dass</strong> sie nicht gern an ihre Schulzeit denkt und sich nicht für das Klassentreffen interessiert.","tag":"Opener 2","en":"On my task sheet a woman says that she does not like thinking about her school days and is not interested in the class reunion."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> nicht jeder gute Erinnerungen an die Schule hat.","tag":"Opener 3","en":"I find this opinion interesting, because not everybody has good memories of school."},{"de":"<strong>Meiner Meinung nach ist die Familie wichtiger als Geld oder Karriere.</strong>","tag":"Family 2, opinion","en":"In my opinion family is more important than money or career."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass man mit zwei Kindern viel Hilfe von der Familie braucht.</strong>","tag":"Family 2, experience","en":"I have found that with two children you need a lot of help from the family."},{"de":"<strong>In meinem Heimatland feiern wir oft mit der ganzen Familie, manchmal mit über hundert Gästen.</strong>","tag":"Family 2, home country","en":"In my home country we often celebrate with the whole family, sometimes with over a hundred guests."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}]}},{"no":48,"title":"Führerschein","A":{"who":"","text":"(Yvonne Hector) Ich bin so froh, dass ich einen Führerschein habe. Das erleichtert mir meinen Alltag. Es ist so viel angenehmer, mit dem Auto zur Arbeit zu fahren. Ich muss keine lauten Menschen ertragen und ich habe meine Ruhe. Wenn ich privat etwas unternehmen möchte, bin ich sehr flexibel."},"B":{"who":"","text":"(Sebastian Hubrich) Ich brauche keinen Führerschein. Da ich sowieso in der Stadt lebe, komme ich mit Straßenbahnen und Bussen sehr schnell voran. Manchmal nerven mich meine Mitmenschen, aber für unsere Umwelt sind die öffentlichen Verkehrsmittel auf jeden Fall die bessere Option."},"en":"Driving licence","sol":{"A":[{"de":"<strong>Es geht um das Thema</strong> „Führerschein“.","tag":"Opener 1","en":"The topic is \"driving licence\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> eine Frau, <strong>dass</strong> ein Führerschein ihren Alltag erleichtert und sie damit flexibel ist.","tag":"Opener 2","en":"On my task sheet a woman says that a driving licence makes her everyday life easier and she is flexible with it."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> man im Auto seine Ruhe hat.","tag":"Opener 3","en":"I find this opinion interesting, because you have your peace in the car."},{"de":"<strong>Meiner Meinung nach ist Qualität wichtiger als der Preis.</strong>","tag":"Family 5, opinion","en":"In my opinion quality is more important than the price."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass Bus und Bahn in der Stadt oft schneller sind als das Auto.</strong>","tag":"Family 5, experience","en":"I have found that buses and trains in the city are often faster than the car."},{"de":"<strong>In meinem Heimatland fahren die meisten Leute mit dem Auto oder mit dem Motorrad.</strong>","tag":"Family 5, home country","en":"In my home country most people travel by car or by motorbike."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}],"B":[{"de":"<strong>Es geht um das Thema</strong> „Führerschein“.","tag":"Opener 1","en":"The topic is \"driving licence\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> ein Mann, <strong>dass</strong> er keinen Führerschein braucht und lieber mit Bus und Straßenbahn fährt.","tag":"Opener 2","en":"On my task sheet a man says that he does not need a driving licence and prefers to take the bus and tram."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> öffentliche Verkehrsmittel besser für die Umwelt sind.","tag":"Opener 3","en":"I find this opinion interesting, because public transport is better for the environment."},{"de":"<strong>Meiner Meinung nach ist Qualität wichtiger als der Preis.</strong>","tag":"Family 5, opinion","en":"In my opinion quality is more important than the price."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass Bus und Bahn in der Stadt oft schneller sind als das Auto.</strong>","tag":"Family 5, experience","en":"I have found that buses and trains in the city are often faster than the car."},{"de":"<strong>In meinem Heimatland fahren die meisten Leute mit dem Auto oder mit dem Motorrad.</strong>","tag":"Family 5, home country","en":"In my home country most people travel by car or by motorbike."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}]}},{"no":49,"title":"Rapmusik","A":{"who":"","text":"(Oliver Schied) Dieser schnelle Sprechgesang ist nichts für mich. Die Texte sind viel zu aggressiv und voller Beleidigungen. Die Hälfte versteht man nicht einmal. Da höre ich lieber ruhigere Poplieder."},"B":{"who":"","text":"(Sina May) Ich liebe Rap. Die Musiker haben immer so interessante und auch wichtige Themen. Es wird nie langweilig. Was mir besonders gut gefällt. Viele Rapper arbeiten mit Sängern zusammen und mischen Rap und Pop."},"en":"Rap music","sol":{"A":[{"de":"<strong>Es geht um das Thema</strong> „Rapmusik“.","tag":"Opener 1","en":"The topic is \"rap music\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> ein Mann, <strong>dass</strong> ihm Rap nicht gefällt und er lieber ruhigere Popmusik hört.","tag":"Opener 2","en":"On my task sheet a man says that he does not like rap and prefers to listen to calmer pop music."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> viele Rap-Texte sehr aggressiv sind.","tag":"Opener 3","en":"I find this opinion interesting, because many rap lyrics are very aggressive."},{"de":"<strong>Meiner Meinung nach braucht jeder Mensch Zeit für seine Hobbys.</strong>","tag":"Family 4, opinion","en":"In my opinion every person needs time for their hobbies."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass ich nach einem langen Spaziergang viel entspannter bin.</strong>","tag":"Family 4, experience","en":"I have found that I am much more relaxed after a long walk."},{"de":"<strong>In meinem Heimatland verbringen viele Leute ihre Freizeit mit der Familie.</strong>","tag":"Family 4, home country","en":"In my home country many people spend their free time with their family."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}],"B":[{"de":"<strong>Es geht um das Thema</strong> „Rapmusik“.","tag":"Opener 1","en":"The topic is \"rap music\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> eine Frau, <strong>dass</strong> sie Rap liebt und die Themen interessant findet.","tag":"Opener 2","en":"On my task sheet a woman says that she loves rap and finds the topics interesting."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> Rap oft wichtige Themen anspricht.","tag":"Opener 3","en":"I find this opinion interesting, because rap often talks about important topics."},{"de":"<strong>Meiner Meinung nach braucht jeder Mensch Zeit für seine Hobbys.</strong>","tag":"Family 4, opinion","en":"In my opinion every person needs time for their hobbies."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass ich nach einem langen Spaziergang viel entspannter bin.</strong>","tag":"Family 4, experience","en":"I have found that I am much more relaxed after a long walk."},{"de":"<strong>In meinem Heimatland verbringen viele Leute ihre Freizeit mit der Familie.</strong>","tag":"Family 4, home country","en":"In my home country many people spend their free time with their family."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}]}},{"no":51,"title":"Kleidung","A":{"who":"","text":"Ich kaufe nicht so viele Klamotten, aber wenn ich etwas kaufe, achte ich immer auf die Qualität. Schließlich möchte ich lange tragen und nicht nach kurzer Zeit weg."},"B":{"who":"","text":"Ich habe nicht viel Zeit zum Shoppen. Hemden oder Hosen kaufe ich meistens, wenn ich in der Stadt bin und etwas zu tun habe. Ich probiere sie nicht einmal an. Wenn ich sie wieder trage, gefallen sie mir nicht mehr. Oder nach dem ersten Waschen merke ich, dass sie zu billig sind und die Farben nicht mehr so gut sind wie vorher."},"en":"Clothes","tr":{"A":"Person A (no name): \"I do not buy many clothes, but when I buy something, I always pay attention to the quality. After all, I want to wear it for a long time and not throw it away after a short time.\"","B":"Person B (no name): \"I do not have much time for shopping. I mostly buy shirts or trousers when I am in town and have something to do. I do not even try them on. When I wear them again, I do not like them any more. Or after the first wash I notice that they are too cheap and the colours are not as good as before.\""},"sol":{"A":[{"de":"<strong>Es geht um das Thema</strong> „Kleidung“.","tag":"Opener 1","en":"The topic is \"clothes\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> eine Person, <strong>dass</strong> sie nicht so viele Kleider kauft, aber immer auf die Qualität achtet.","tag":"Opener 2","en":"On my task sheet a person says that they do not buy many clothes, but always pay attention to quality."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> billige Kleidung schnell kaputtgeht.","tag":"Opener 3","en":"I find this opinion interesting, because cheap clothes break quickly."},{"de":"<strong>Meiner Meinung nach ist Qualität wichtiger als der Preis.</strong>","tag":"Family 5, opinion (exact)","en":"In my opinion quality is more important than the price."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass</strong> gute Kleidung viel länger hält.","tag":"Family 5, experience (start only)","en":"I have found that good clothes last much longer."},{"de":"<strong>In meinem Heimatland</strong> kaufen <strong>die meisten Leute</strong> ihre Kleidung auf dem Markt.","tag":"Family 5, home country (start only)","en":"In my home country most people buy their clothes at the market."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}],"B":[{"de":"<strong>Es geht um das Thema</strong> „Kleidung“.","tag":"Opener 1","en":"The topic is \"clothes\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> eine Person, <strong>dass</strong> sie wenig Zeit zum Einkaufen hat. Sie probiert die Kleidung nicht an.","tag":"Opener 2","en":"On my task sheet a person says that they have little time for shopping. They do not try the clothes on."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> viele Leute wenig Zeit haben.","tag":"Opener 3","en":"I find this opinion interesting, because many people have little time."},{"de":"<strong>Meiner Meinung nach ist Qualität wichtiger als der Preis.</strong>","tag":"Family 5, opinion (exact)","en":"In my opinion quality is more important than the price."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass</strong> gute Kleidung viel länger hält.","tag":"Family 5, experience (start only)","en":"I have found that good clothes last much longer."},{"de":"<strong>In meinem Heimatland</strong> kaufen <strong>die meisten Leute</strong> ihre Kleidung auf dem Markt.","tag":"Family 5, home country (start only)","en":"In my home country most people buy their clothes at the market."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}]}},{"no":52,"title":"Handy","A":{"who":"","text":"Das Thema ist nicht neu, aber sehr sehr nervig. Überall sieht man Menschen, die sich mit ihren Handys beschäftigen. Das kann doch nicht sein, dass ein kleines Gerät unser ganzes Leben bestimmt. Nicht einmal auf der Autobahn können Menschen die Finger davon lassen."},"B":{"who":"","text":"Mein Handy ist mein ständiger Begleiter. Inzwischen kann ich ohne Geld und Schlüssel das Haus verlassen, aber nicht ohne mein Handy. Und ich muss zugeben, zum Telefonieren brauche ich es gar nicht so oft. Viel wichtiger sind mein Terminplaner und meine Apps."},"en":"Mobile phone","sol":{"A":[{"de":"<strong>Es geht um das Thema</strong> „Handy“.","tag":"Opener 1","en":"The topic is \"mobile phone\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> eine Person, <strong>dass</strong> ein kleines Gerät nicht unser ganzes Leben bestimmen sollte.","tag":"Opener 2","en":"On my task sheet a person says that a small device should not determine our whole life."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> man sogar beim Autofahren aufs Handy schaut.","tag":"Opener 3","en":"I find this opinion interesting, because people even look at their phone while driving."},{"de":"<strong>Meiner Meinung nach ist das Handy praktisch, aber man sollte es nicht zu oft benutzen.</strong>","tag":"Family 1, opinion","en":"In my opinion the phone is practical, but you should not use it too often."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass ich ohne Handy besser schlafe und mehr Zeit für meine Familie habe.</strong>","tag":"Family 1, experience","en":"I have found that I sleep better without my phone and have more time for my family."},{"de":"<strong>In meinem Heimatland benutzen fast alle jungen Leute den ganzen Tag ihr Handy.</strong>","tag":"Family 1, home country","en":"In my home country almost all young people use their phones all day."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}],"B":[{"de":"<strong>Es geht um das Thema</strong> „Handy“.","tag":"Opener 1","en":"The topic is \"mobile phone\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> eine Person, <strong>dass</strong> sie ihr Handy immer dabeihat und vor allem die Apps und den Terminplaner nutzt.","tag":"Opener 2","en":"On my task sheet a person says that they always have their phone with them and mainly use the apps and the diary."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> ein Handy im Alltag sehr praktisch ist.","tag":"Opener 3","en":"I find this opinion interesting, because a phone is very practical in everyday life."},{"de":"<strong>Meiner Meinung nach ist das Handy praktisch, aber man sollte es nicht zu oft benutzen.</strong>","tag":"Family 1, opinion","en":"In my opinion the phone is practical, but you should not use it too often."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass ich ohne Handy besser schlafe und mehr Zeit für meine Familie habe.</strong>","tag":"Family 1, experience","en":"I have found that I sleep better without my phone and have more time for my family."},{"de":"<strong>In meinem Heimatland benutzen fast alle jungen Leute den ganzen Tag ihr Handy.</strong>","tag":"Family 1, home country","en":"In my home country almost all young people use their phones all day."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}]}},{"no":53,"title":"Abenteuer","A":{"who":"","text":"Markus Traut Ich hatte schon einige echte Grenzerfahrungen. Zum Beispiel haben wir in Nambia wilde Tiere aus nächster Nähe beobachtet. Das war unvergesslich. Und beim Freeclimbing (Klettern oder Hilfsmittel) und Tauchen mit Haien hatte ich diesen Adrenalinkick."},"B":{"who":"","text":"Sibel Ortaköy Das Besondere finde ich meistens im Sommerurlaub an schönen Orten. Das kann am Meer sein oder auf einem Berg oder in einem Tal. Dort verweile ich dann für viele Stunden und genieße die Aussicht."},"en":"Adventure","sol":{"A":[{"de":"<strong>Es geht um das Thema</strong> „Abenteuer“.","tag":"Opener 1","en":"The topic is \"adventure\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> ein Mann, <strong>dass</strong> er schon echte Abenteuer erlebt hat, zum Beispiel wilde Tiere in Namibia beobachtet und beim Klettern und Tauchen.","tag":"Opener 2","en":"On my task sheet a man says that he has already had real adventures, for example watching wild animals in Namibia, climbing and diving."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> solche Erlebnisse unvergesslich sind.","tag":"Opener 3","en":"I find this opinion interesting, because such experiences are unforgettable."},{"de":"<strong>Meiner Meinung nach braucht jeder Mensch Zeit für seine Hobbys.</strong>","tag":"Family 4, opinion","en":"In my opinion every person needs time for their hobbies."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass ich nach einem langen Spaziergang viel entspannter bin.</strong>","tag":"Family 4, experience","en":"I have found that I am much more relaxed after a long walk."},{"de":"<strong>In meinem Heimatland verbringen viele Leute ihre Freizeit mit der Familie.</strong>","tag":"Family 4, home country","en":"In my home country many people spend their free time with their family."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}],"B":[{"de":"<strong>Es geht um das Thema</strong> „Abenteuer“.","tag":"Opener 1","en":"The topic is \"adventure\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> eine Frau, <strong>dass</strong> sie das Besondere im Sommerurlaub an schönen Orten findet.","tag":"Opener 2","en":"On my task sheet a woman says that she finds what is special on summer holidays in beautiful places."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> man dort die Aussicht genießen und sich erholen kann.","tag":"Opener 3","en":"I find this opinion interesting, because you can enjoy the view and relax there."},{"de":"<strong>Meiner Meinung nach braucht jeder Mensch Zeit für seine Hobbys.</strong>","tag":"Family 4, opinion","en":"In my opinion every person needs time for their hobbies."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass ich nach einem langen Spaziergang viel entspannter bin.</strong>","tag":"Family 4, experience","en":"I have found that I am much more relaxed after a long walk."},{"de":"<strong>In meinem Heimatland verbringen viele Leute ihre Freizeit mit der Familie.</strong>","tag":"Family 4, home country","en":"In my home country many people spend their free time with their family."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}]}},{"no":54,"title":"Rauchen","A":{"who":"","text":"In Deutschland zeigt die Zahl der Exzessivraucher, also der Menschen, die mehr als 20 Zigaretten am Tag rauchen, sehr deutlich, dass Rauchen nicht gut für die Gesundheit ist. Ich finde, in unserer Zeit spielen Fitness, Ernährung und das richtige Gewicht eine wichtige Rolle. Darum denke ich, dass Rauchen unseren Körper sehr stark stört."},"B":{"who":"","text":"Das Rauchen ist vielleicht nicht gut, aber ich finde Rauchen nicht so schlimm. Es hilft mir, mich zu entspannen, besonders nach der Arbeit. Viele meiner Freunde rauchen auch, und niemand ist wirklich krank deswegen."},"en":"Smoking","sol":{"A":[{"de":"<strong>Es geht um das Thema</strong> „Rauchen“.","tag":"Opener 1","en":"The topic is \"smoking\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> eine Person, <strong>dass</strong> Rauchen schlecht für die Gesundheit ist.","tag":"Opener 2","en":"On my task sheet a person says that smoking is bad for your health."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> Fitness und gesunde Ernährung heute wichtig sind.","tag":"Opener 3","en":"I find this opinion interesting, because fitness and healthy food are important today."},{"de":"<strong>Meiner Meinung nach ist Gesundheit wichtiger als alles andere.</strong>","tag":"Family 6, opinion","en":"In my opinion health is more important than anything else."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass ich mit dem täglichen Spaziergang weniger Stress habe.</strong>","tag":"Family 6, experience","en":"I have found that I have less stress with my daily walk."},{"de":"<strong>In meinem Heimatland ist das Essen sehr scharf, und wir kochen fast jeden Tag frisch.</strong>","tag":"Family 6, home country","en":"In my home country the food is very spicy, and we cook fresh almost every day."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}],"B":[{"de":"<strong>Es geht um das Thema</strong> „Rauchen“.","tag":"Opener 1","en":"The topic is \"smoking\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> eine Person, <strong>dass</strong> sie Rauchen nicht so schlimm findet und sich dabei entspannt.","tag":"Opener 2","en":"On my task sheet a person says that they do not find smoking so bad and relax while doing it."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> viele Menschen rauchen, um Stress abzubauen.","tag":"Opener 3","en":"I find this opinion interesting, because many people smoke to reduce stress."},{"de":"<strong>Meiner Meinung nach ist Gesundheit wichtiger als alles andere.</strong>","tag":"Family 6, opinion","en":"In my opinion health is more important than anything else."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass ich mit dem täglichen Spaziergang weniger Stress habe.</strong>","tag":"Family 6, experience","en":"I have found that I have less stress with my daily walk."},{"de":"<strong>In meinem Heimatland ist das Essen sehr scharf, und wir kochen fast jeden Tag frisch.</strong>","tag":"Family 6, home country","en":"In my home country the food is very spicy, and we cook fresh almost every day."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}]}},{"no":55,"title":"Wohnen in der Stadt oder auf dem Land","A":{"who":"Marcel Köstner, 25 Jahre, Student","text":"Ich wohne am liebsten in der Stadt. Wichtig sind für mich gute und nahe Einkaufsmöglichkeiten, kurze Wege zur Arbeit, ein attraktives Freizeitangebot, Kultur und Leben auf der Straße. Ich wohne allein, in einer kleinen Wohnung mieten in der Stadt. Ich möchte aber bald mit meiner Freundin zusammenziehen. Ideal wäre für uns dann eine Wohnung in einer ruhigen Straße mit guten Verkehrsverbindungen zum Zentrum."},"B":{"who":"Ilona Schmidt,40 Jahre, Lehrerin","text":"Wir haben lange in der Stadt gewohnt und sind jetzt aufs Land gezogen. Irgendwann haben wir den Verkehrslärm und die Hektik nicht mehr ausgehalten, und als Tim, unser Sohn, geboren wurde, haben wir uns entschieden, in ein kleines Dorf zu ziehen. Wir wohnen jetzt in einem Einfamilienhaus, so etwas hätten wir in der Stadt nicht gefunden. Dort sind die Mieten einfach zu hoch. Wir haben einen schönen Garten, wir genießen die Ruhe, die Natur und die gute Luft. Der einzige Nachteil ist, dass wir fast alles mit dem Auto machen müssen. (1 số Thema mới chỉ có 1 Person, chưa có thông tin Person còn lại)"},"en":"Living in the city or in the countryside","sol":{"A":[{"de":"<strong>Es geht um das Thema</strong> „Wohnen in der Stadt oder auf dem Land“.","tag":"Opener 1","en":"The topic is \"living in the city or the countryside\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> ein junger Mann, <strong>dass</strong> er am liebsten in der Stadt wohnt.","tag":"Opener 2","en":"On my task sheet a young man says that he prefers living in the city."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> man dort kurze Wege und viel Kultur hat.","tag":"Opener 3","en":"I find this opinion interesting, because you have short distances and a lot of culture there."},{"de":"<strong>Meiner Meinung nach ist eine ruhige Lage wichtiger als eine große Wohnung.</strong>","tag":"Family 3, opinion","en":"In my opinion a quiet location is more important than a big flat."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass Wohnungen in München sehr teuer sind.</strong>","tag":"Family 3, experience","en":"I have found that flats in Munich are very expensive. (Use your own city.)"},{"de":"<strong>In meinem Heimatland wohnen die Kinder meistens bei den Eltern, bis sie heiraten.</strong>","tag":"Family 3, home country","en":"In my home country children mostly live with their parents until they marry."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}],"B":[{"de":"<strong>Es geht um das Thema</strong> „Wohnen in der Stadt oder auf dem Land“.","tag":"Opener 1","en":"The topic is \"living in the city or the countryside\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> eine Frau, <strong>dass</strong> sie mit ihrer Familie aufs Land gezogen ist und dort ein Haus mit Garten hat.","tag":"Opener 2","en":"On my task sheet a woman says that she moved to the countryside with her family and has a house with a garden there."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> es auf dem Land ruhiger ist.","tag":"Opener 3","en":"I find this opinion interesting, because it is quieter in the countryside."},{"de":"<strong>Meiner Meinung nach ist eine ruhige Lage wichtiger als eine große Wohnung.</strong>","tag":"Family 3, opinion","en":"In my opinion a quiet location is more important than a big flat."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass Wohnungen in München sehr teuer sind.</strong>","tag":"Family 3, experience","en":"I have found that flats in Munich are very expensive. (Use your own city.)"},{"de":"<strong>In meinem Heimatland wohnen die Kinder meistens bei den Eltern, bis sie heiraten.</strong>","tag":"Family 3, home country","en":"In my home country children mostly live with their parents until they marry."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}]}},{"no":47,"title":"An Wochenenden etwas unternehmen?","A":{"who":"","text":"Ich freue mich immer auf das Wochenende. Gemeinsam mit meinen Freund:innen planen wir, was wir machen wollen. Oft gehen wir ins Restaurant, ins Kino oder ins Konzert. Wenn wir überhaupt keine Ideen haben, treffen wir uns bei mir und machen uns einen gemütlichen Abend."},"B":null,"en":"Doing something at weekends?","sol":{"A":[{"de":"<strong>Es geht um das Thema</strong> „An Wochenenden etwas unternehmen“.","tag":"Opener 1","en":"The topic is \"doing things at weekends\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> eine Person, <strong>dass</strong> sie sich immer auf das Wochenende freut und mit Freunden etwas unternimmt.","tag":"Opener 2","en":"On my task sheet a person says that she always looks forward to the weekend and does something with friends."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> man am Wochenende Zeit für Freunde hat.","tag":"Opener 3","en":"I find this opinion interesting, because you have time for friends at the weekend."},{"de":"<strong>Meiner Meinung nach braucht jeder Mensch Zeit für seine Hobbys.</strong>","tag":"Family 4, opinion","en":"In my opinion every person needs time for their hobbies."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass ich nach einem langen Spaziergang viel entspannter bin.</strong>","tag":"Family 4, experience","en":"I have found that I am much more relaxed after a long walk."},{"de":"<strong>In meinem Heimatland verbringen viele Leute ihre Freizeit mit der Familie.</strong>","tag":"Family 4, home country","en":"In my home country many people spend their free time with their family."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}]}},{"no":50,"title":"Immer Online","A":null,"B":{"who":"","text":"Ich bin immer online, den Überstag arbeite ich am Computer. abends sitze ich mit meinem Notebook, ich spiele Musikinstrumente und etwas arbeiten, danach ruhe ich mich aus. Ich habe das Gefühl, ich könnte online gehen, aber ich fühle mich nicht gut."},"en":"Always online","sol":{"B":[{"de":"<strong>Es geht um das Thema</strong> „Immer online“.","tag":"Opener 1","en":"The topic is \"always online\"."},{"de":"<strong>Auf meinem Aufgabenblatt sagt</strong> eine Person, <strong>dass</strong> sie immer online ist und den ganzen Tag am Computer arbeitet.","tag":"Opener 2","en":"On my task sheet a person says that they are always online and work at the computer all day."},{"de":"<strong>Diese Meinung finde ich interessant, weil</strong> viele Menschen heute ständig online sind.","tag":"Opener 3","en":"I find this opinion interesting, because many people are constantly online today."},{"de":"<strong>Meiner Meinung nach ist das Handy praktisch, aber man sollte es nicht zu oft benutzen.</strong>","tag":"Family 1, opinion","en":"In my opinion the phone is practical, but you should not use it too often."},{"de":"<strong>Ich habe die Erfahrung gemacht, dass ich ohne Handy besser schlafe und mehr Zeit für meine Familie habe.</strong>","tag":"Family 1, experience","en":"I have found that I sleep better without my phone and have more time for my family."},{"de":"<strong>In meinem Heimatland benutzen fast alle jungen Leute den ganzen Tag ihr Handy.</strong>","tag":"Family 1, home country","en":"In my home country almost all young people use their phones all day."},{"de":"<strong>Was meinst du? Wie ist das bei dir?</strong>","tag":"Opener 6","en":"What do you think? How is it for you?"}]}}];
